def _test_worker_frame_binding(frame) -> dict:
    return {
        key: frame["header"][key]
        for key in WORKER_FRAME_BINDING_FIELDS
    }


def _test_frame_record_from_supplied_header(
    header: dict,
    payload: bytes,
) -> types.MappingProxyType:
    copied_header = dict(header)
    return types.MappingProxyType(
        {
            "header": types.MappingProxyType(copied_header),
            "payload": payload,
            "wire": _test_pack_supplied_worker_frame(
                copied_header,
                payload,
            ),
        }
    )


def _test_replace_only_frame_semantic_sha256(
    frame,
    replacement: str,
) -> types.MappingProxyType:
    if (
        type(replacement) is not str
        or re.fullmatch(r"[0-9a-f]{64}", replacement) is None
        or replacement == frame["header"]["semantic_sha256"]
    ):
        raise AssertionError("semantic-only replacement is not distinct hex")
    header = dict(frame["header"])
    header["semantic_sha256"] = replacement
    rebuilt = _test_frame_record_from_supplied_header(
        header,
        frame["payload"],
    )
    self_same = {
        key: value
        for key, value in frame["header"].items()
        if key != "semantic_sha256"
    }
    rebuilt_same = {
        key: value
        for key, value in rebuilt["header"].items()
        if key != "semantic_sha256"
    }
    if (
        self_same != rebuilt_same
        or rebuilt["payload"] != frame["payload"]
        or rebuilt["header"]["bytes"] != frame["header"]["bytes"]
        or rebuilt["header"]["raw_sha256"]
        != frame["header"]["raw_sha256"]
    ):
        raise AssertionError("semantic-only frame repair changed other data")
    return rebuilt


def _test_rebuild_result_frame_from_raw_payload(
    frame,
    raw_payload: bytes,
) -> types.MappingProxyType:
    """Rebuild mechanics around opaque raw bytes without decoding them."""
    if type(raw_payload) is not bytes:
        raise AssertionError("raw typed-result negative is not bytes")
    if raw_payload == frame["payload"]:
        raise AssertionError("raw result rebuild payload is unchanged")
    original = dict(frame["header"])
    header = dict(original)
    header["bytes"] = len(raw_payload)
    header["raw_sha256"] = hashlib.sha256(raw_payload).hexdigest()
    header["semantic_sha256"] = hashlib.sha256(
        b"f5-canonical-json-v1\0" + raw_payload
    ).hexdigest()
    mechanical = {"bytes", "raw_sha256", "semantic_sha256"}
    observed_header_diff = {
        key
        for key in set(original) | set(header)
        if key not in original
        or key not in header
        or type(original[key]) is not type(header[key])
        or original[key] != header[key]
    }
    if (
        not observed_header_diff
        or not observed_header_diff <= mechanical
        or not {"raw_sha256", "semantic_sha256"}
        <= observed_header_diff
    ):
        raise AssertionError(
            "raw result rebuild mechanical header diff drifted: %r"
            % (observed_header_diff,)
        )
    if {
        key: value
        for key, value in header.items()
        if key not in mechanical
    } != {
        key: value
        for key, value in original.items()
        if key not in mechanical
    }:
        raise AssertionError("raw result rebuild changed nonmechanical fields")
    rebuilt = _test_frame_record_from_supplied_header(header, raw_payload)
    if rebuilt["header"]["bytes"] != len(raw_payload):
        raise AssertionError("raw result byte count was not rebuilt")
    return rebuilt


def _test_typed_value_diff_paths(before, after, prefix=()):
    if type(before) is dict and type(after) is dict:
        differences = []
        for key in sorted(set(before) | set(after)):
            path = (*prefix, key)
            if key not in before or key not in after:
                differences.append(path)
            else:
                differences.extend(
                    _test_typed_value_diff_paths(
                        before[key],
                        after[key],
                        path,
                    )
                )
        return differences
    if type(before) is not type(after) or before != after:
        return [prefix]
    return []


def _test_mutate_canonical_evaluation_result(
    fixture,
    *,
    replacements=None,
    removals=(),
    additions=None,
):
    original = fixture["record"]
    source_snapshot = copy.deepcopy(original)
    mutated = copy.deepcopy(original)
    requested = set()

    def parent_and_leaf(root, path):
        if type(path) is not tuple or not path:
            raise AssertionError("typed-result mutation path is malformed")
        parent = root
        for component in path[:-1]:
            if type(parent) is not dict or component not in parent:
                raise AssertionError("typed-result mutation parent is absent")
            parent = parent[component]
        if type(parent) is not dict:
            raise AssertionError("typed-result mutation parent is not object")
        return parent, path[-1]

    for path in removals:
        parent, leaf = parent_and_leaf(mutated, path)
        if leaf not in parent:
            raise AssertionError("typed-result removal leaf is absent")
        del parent[leaf]
        requested.add(path)
    for path, value in (replacements or {}).items():
        parent, leaf = parent_and_leaf(mutated, path)
        if leaf not in parent:
            raise AssertionError("typed-result replacement leaf is absent")
        if type(parent[leaf]) is type(value) and parent[leaf] == value:
            raise AssertionError("typed-result replacement is unchanged")
        parent[leaf] = copy.deepcopy(value)
        requested.add(path)
    for path, value in (additions or {}).items():
        parent, leaf = parent_and_leaf(mutated, path)
        if leaf in parent:
            raise AssertionError("typed-result addition leaf already exists")
        parent[leaf] = copy.deepcopy(value)
        requested.add(path)
    observed = set(_test_typed_value_diff_paths(source_snapshot, mutated))
    if observed != requested:
        raise AssertionError(
            "typed-result mutation escaped requested leaves: %r != %r"
            % (observed, requested)
        )
    raw = _canonical_json_fixture(mutated)
    frame = _test_rebuild_result_frame_from_raw_payload(
        fixture["frames"][1],
        raw,
    )
    if fixture["record"] != source_snapshot:
        raise AssertionError("typed-result mutator changed its source record")
    return mutated, frame


def _test_rebuild_training_semantic_frame(
    frame,
    raw_payload: bytes,
    *,
    semantic_sha256: str,
) -> types.MappingProxyType:
    """Mechanically reseal one opaque training payload for semantic tests."""
    if type(raw_payload) is not bytes or raw_payload == frame["payload"]:
        raise AssertionError("training semantic payload is not distinct bytes")
    if (
        type(semantic_sha256) is not str
        or re.fullmatch(r"[0-9a-f]{64}", semantic_sha256) is None
        or semantic_sha256 == frame["header"]["semantic_sha256"]
    ):
        raise AssertionError("training semantic digest is not distinct hex")
    original = dict(frame["header"])
    header = dict(original)
    header["bytes"] = len(raw_payload)
    header["raw_sha256"] = hashlib.sha256(raw_payload).hexdigest()
    header["semantic_sha256"] = semantic_sha256
    mechanical = {"bytes", "raw_sha256", "semantic_sha256"}
    observed = {
        key
        for key in set(original) | set(header)
        if key not in original
        or key not in header
        or type(original[key]) is not type(header[key])
        or original[key] != header[key]
    }
    if (
        not {"raw_sha256", "semantic_sha256"} <= observed
        or not observed <= mechanical
        or {
            key: value
            for key, value in original.items()
            if key not in mechanical
        }
        != {
            key: value
            for key, value in header.items()
            if key not in mechanical
        }
    ):
        raise AssertionError(
            "training semantic frame escaped mechanical reseal: %r"
            % (observed,)
        )
    rebuilt = _test_frame_record_from_supplied_header(header, raw_payload)
    if rebuilt["header"]["bytes"] != len(raw_payload):
        raise AssertionError("training semantic byte count was not rebuilt")
    return rebuilt


def _test_canonical_tensor_sha256_from_raw_slices(raw: bytes) -> str:
    """Frame exact tensor bytes without decoding or finiteness filtering."""
    if type(raw) is not bytes or len(raw) != 879900:
        raise AssertionError("direct tensor preimage has wrong byte geometry")
    framed = bytearray(b"f5-canonical-tensors-v1\0")
    framed.extend(struct.pack(">I", len(EXPECTED_TENSOR_SCHEMA)))
    offset = 0
    for name, shape, size in EXPECTED_TENSOR_SCHEMA:
        name_bytes = name.encode("ascii")
        dtype = b"float32-le"
        payload = raw[offset : offset + size]
        if len(payload) != size:
            raise AssertionError("direct tensor slice is truncated")
        framed.extend(struct.pack(">I", len(name_bytes)))
        framed.extend(name_bytes)
        framed.extend(struct.pack(">I", len(dtype)))
        framed.extend(dtype)
        framed.extend(struct.pack(">I", len(shape)))
        for dimension in shape:
            framed.extend(struct.pack(">Q", dimension))
        framed.extend(struct.pack(">Q", len(payload)))
        framed.extend(payload)
        offset += size
    if offset != len(raw):
        raise AssertionError("direct tensor framing left trailing bytes")
    return hashlib.sha256(framed).hexdigest()


def _test_training_typed_value_diff_paths(
    before,
    after,
    prefix=(),
):
    """Return exact dict-key/list-index leaves changed by one mutation."""
    if type(before) is dict and type(after) is dict:
        differences = []
        for key in sorted(set(before) | set(after)):
            path = (*prefix, key)
            if key not in before or key not in after:
                differences.append(path)
            else:
                differences.extend(
                    _test_training_typed_value_diff_paths(
                        before[key],
                        after[key],
                        path,
                    )
                )
        return differences
    if (
        type(before) is list
        and type(after) is list
        and len(before) == len(after)
    ):
        differences = []
        for index, (left, right) in enumerate(zip(before, after, strict=True)):
            differences.extend(
                _test_training_typed_value_diff_paths(
                    left,
                    right,
                    (*prefix, index),
                )
            )
        return differences
    if type(before) is not type(after) or before != after:
        return [prefix]
    return []


def _test_mutate_canonical_training_result(
    fixture,
    *,
    replacements=None,
    removals=(),
    additions=None,
):
    """Mutate only requested training-result leaves, including list indices."""
    original = fixture["record"]
    source_snapshot = copy.deepcopy(original)
    mutated = copy.deepcopy(original)
    requested = set()

    def descend(root, path):
        if type(path) is not tuple or not path:
            raise AssertionError("training-result mutation path is malformed")
        parent = root
        for component in path[:-1]:
            if type(parent) is dict:
                if type(component) is not str or component not in parent:
                    raise AssertionError(
                        "training-result mutation object parent is absent"
                    )
                parent = parent[component]
            elif type(parent) is list:
                if (
                    type(component) is not int
                    or not 0 <= component < len(parent)
                ):
                    raise AssertionError(
                        "training-result mutation list index is absent"
                    )
                parent = parent[component]
            else:
                raise AssertionError(
                    "training-result mutation traversed a scalar"
                )
        return parent, path[-1]

    def get_leaf(parent, leaf):
        if type(parent) is dict:
            if type(leaf) is not str or leaf not in parent:
                raise AssertionError("training-result object leaf is absent")
            return parent[leaf]
        if type(parent) is list:
            if type(leaf) is not int or not 0 <= leaf < len(parent):
                raise AssertionError("training-result list leaf is absent")
            return parent[leaf]
        raise AssertionError("training-result leaf parent is scalar")

    def set_leaf(parent, leaf, value):
        get_leaf(parent, leaf)
        parent[leaf] = copy.deepcopy(value)

    for path in removals:
        parent, leaf = descend(mutated, path)
        if type(parent) is not dict:
            raise AssertionError("training-result removal is not object leaf")
        get_leaf(parent, leaf)
        del parent[leaf]
        if path in requested:
            raise AssertionError("duplicate training-result mutation path")
        requested.add(path)
    for path, value in (replacements or {}).items():
        parent, leaf = descend(mutated, path)
        prior = get_leaf(parent, leaf)
        if type(prior) is type(value) and prior == value:
            raise AssertionError("training-result replacement is unchanged")
        set_leaf(parent, leaf, value)
        if path in requested:
            raise AssertionError("duplicate training-result mutation path")
        requested.add(path)
    for path, value in (additions or {}).items():
        parent, leaf = descend(mutated, path)
        if type(parent) is not dict or type(leaf) is not str:
            raise AssertionError("training-result addition is not object leaf")
        if leaf in parent:
            raise AssertionError("training-result addition leaf exists")
        parent[leaf] = copy.deepcopy(value)
        if path in requested:
            raise AssertionError("duplicate training-result mutation path")
        requested.add(path)
    if not requested:
        raise AssertionError("training-result mutation is vacuous")
    if any(
        left != right
        and (
            left[: len(right)] == right
            or right[: len(left)] == left
        )
        for left in requested
        for right in requested
    ):
        raise AssertionError("training-result mutation paths overlap")
    raw_observed = set(
        _test_training_typed_value_diff_paths(source_snapshot, mutated)
    )
    observed = set()
    for raw_path in raw_observed:
        owners = {
            requested_path
            for requested_path in requested
            if raw_path[: len(requested_path)] == requested_path
        }
        if len(owners) != 1:
            raise AssertionError(
                "training-result mutation escaped requested leaves: %r"
                % (raw_path,)
            )
        observed.update(owners)
    if observed != requested:
        raise AssertionError(
            "training-result mutation escaped requested leaves: %r != %r"
            % (observed, requested)
        )
    raw = _canonical_json_fixture(mutated)
    frame = _test_rebuild_result_frame_from_raw_payload(
        fixture["frames"][7],
        raw,
    )
    if fixture["record"] != source_snapshot:
        raise AssertionError("training-result mutator changed source fixture")
    return mutated, frame


def _test_build_worker_failure_frame(
    fixture,
    *,
    record=None,
    raw_payload=None,
):
    """Build one job-bound, internally self-consistent failure frame."""
    if (record is None) == (raw_payload is None):
        raise AssertionError(
            "worker-failure frame requires exactly one payload source"
        )
    if record is not None:
        if type(record) is not dict:
            raise AssertionError("worker-failure record is not an object")
        raw_payload = _canonical_json_fixture(record)
    if (
        type(raw_payload) is not bytes
        or not raw_payload
        or len(raw_payload) > 4096
    ):
        raise AssertionError("worker-failure payload escaped exact bounds")
    job = fixture["job"]
    job_sha256 = _test_worker_job_sha256(job)
    frame = _test_build_self_consistent_worker_frame(
        payload=raw_payload,
        frame_index=0,
        kind="worker-failure",
        logical_name="<worker-failure>",
        job_sha256=job_sha256,
        nonce=job["nonce"],
        semantic_sha256=hashlib.sha256(
            b"f5-canonical-json-v1\0" + raw_payload
        ).hexdigest(),
    )
    header = frame["header"]
    if (
        header["bytes"] != len(raw_payload)
        or header["frame_index"] != 0
        or header["job_sha256"] != job_sha256
        or header["kind"] != "worker-failure"
        or header["logical_name"] != "<worker-failure>"
        or header["nonce"] != job["nonce"]
        or header["raw_sha256"]
        != hashlib.sha256(raw_payload).hexdigest()
        or header["semantic_sha256"]
        != hashlib.sha256(
            b"f5-canonical-json-v1\0" + raw_payload
        ).hexdigest()
        or frame["wire"]
        != _test_pack_supplied_worker_frame(dict(header), raw_payload)
    ):
        raise AssertionError("worker-failure frame reseal drifted")
    return frame


