def _wait_readable(read_fd: int, remaining: float) -> bool:
    return bool(select.select((read_fd,), (), (), remaining)[0])


def _pipe_containing(
    payload: bytes,
    *,
    close_writer: bool,
) -> tuple[int, int | None]:
    read_fd, write_fd = os.pipe()
    try:
        if payload:
            written = os.write(write_fd, payload)
            if written != len(payload):
                raise AssertionError("fixture pipe write was short")
        if close_writer:
            os.close(write_fd)
            write_fd = None
        return read_fd, write_fd
    except BaseException:
        os.close(read_fd)
        os.close(write_fd)
        raise


def _close_fd(fd: int | None) -> None:
    if fd is not None:
        try:
            os.close(fd)
        except OSError as error:
            if error.errno != errno.EBADF:
                raise


def _nested_value(root: dict, dotted: str):
    value = root
    for component in dotted.split("."):
        value = value[component]
    return value


def _walk_numeric_values(value):
    if isinstance(value, dict):
        for child in value.values():
            yield from _walk_numeric_values(child)
    elif isinstance(value, (list, tuple)):
        for child in value:
            yield from _walk_numeric_values(child)
    elif type(value) in (int, float):
        yield value


def _test_owned_muon_snapshot(optimizer, policy) -> bytes:
    if (
        type(optimizer).__module__ != "pufferlib.muon"
        or type(optimizer).__name__ != "Muon"
    ):
        raise AssertionError("live optimizer is not exact pufferlib.muon.Muon")
    expected_scalars = {"eps", "lr", "momentum", "weight_decay"}
    if set(optimizer.defaults) != expected_scalars:
        raise AssertionError("Muon defaults are not closed")
    if type(optimizer.param_groups) is not list or len(
        optimizer.param_groups
    ) != 1:
        raise AssertionError("Muon must have exactly one parameter group")
    group = optimizer.param_groups[0]
    if set(group) != {*expected_scalars, "params"}:
        raise AssertionError("Muon parameter group is not closed")

    named_parameters = list(policy.named_parameters())
    names = [name for name, _parameter in named_parameters]
    if names != list(MUON_PARAMETER_ORDER):
        raise AssertionError("live Policy/Muon parameter order drifted")
    if len({id(parameter) for _name, parameter in named_parameters}) != 7:
        raise AssertionError("live policy parameters are not bijective")
    name_by_id = {
        id(parameter): name for name, parameter in named_parameters
    }
    group_parameters = group["params"]
    if type(group_parameters) is not list:
        raise AssertionError("Muon group params must be a list")
    try:
        group_names = [name_by_id[id(parameter)] for parameter in group_parameters]
    except KeyError as error:
        raise AssertionError(
            "Muon group contains a non-policy parameter"
        ) from error
    if group_names != list(MUON_PARAMETER_ORDER):
        raise AssertionError("Muon group parameter order drifted")
    if len({id(parameter) for parameter in group_parameters}) != 7:
        raise AssertionError("Muon group parameter membership drifted")
    if {id(parameter) for parameter in optimizer.state} != set(name_by_id):
        raise AssertionError("Muon state key membership drifted")

    def scalar_hex(value):
        if type(value) not in (int, float):
            raise AssertionError("Muon scalar is not numeric")
        return struct.pack(">d", float(value)).hex()

    state_rows = []
    raw_rows = []
    for parameter_name, parameter in sorted(
        named_parameters,
        key=lambda item: item[0].encode("utf-8"),
    ):
        state = optimizer.state[parameter]
        if set(state) != {"momentum_buffer"}:
            raise AssertionError("Muon state row is not closed")
        tensor = state["momentum_buffer"]
        detached = tensor.detach()
        if str(detached.device) != "cpu":
            raise AssertionError("Muon momentum is not on CPU")
        if str(detached.dtype) != "torch.float32":
            raise AssertionError("Muon momentum is not float32")
        if str(detached.layout) != "torch.strided":
            raise AssertionError("Muon momentum is not strided")
        if not detached.is_contiguous():
            raise AssertionError("Muon momentum is not contiguous")
        shape = [int(value) for value in detached.shape]
        stride = [int(value) for value in detached.stride()]
        storage_offset = int(detached.storage_offset())
        element_count = int(detached.numel())
        byte_count = element_count * int(detached.element_size())
        raw = detached.numpy().tobytes(order="C")
        if len(raw) != byte_count:
            raise AssertionError("Muon momentum byte count drifted")
        state_rows.append(
            {
                "byte_count": byte_count,
                "dtype": "float32",
                "element_count": element_count,
                "name": parameter_name,
                "raw_sha256": hashlib.sha256(raw).hexdigest(),
                "requires_grad": bool(detached.requires_grad),
                "shape": shape,
                "storage_offset": storage_offset,
                "stride": stride,
            }
        )
        raw_rows.append(raw)
    if sum(len(raw) for raw in raw_rows) != 879900:
        raise AssertionError("Muon momentum bytes do not total 879900")

    metadata = {
        "class": "pufferlib.muon.Muon",
        "defaults": {
            key: scalar_hex(optimizer.defaults[key])
            for key in sorted(expected_scalars)
        },
        "parameter_group": {
            **{
                key: scalar_hex(group[key])
                for key in sorted(expected_scalars)
            },
            "params": group_names,
        },
        "schema": "bloodbowl-f5-muon-snapshot-v1",
        "state": state_rows,
    }
    metadata_bytes = _canonical_json_fixture(metadata)
    framed = bytearray(b"bloodbowl-f5-muon-snapshot-v1\0")
    framed.extend(struct.pack(">Q", len(metadata_bytes)))
    framed.extend(metadata_bytes)
    for raw in raw_rows:
        framed.extend(struct.pack(">Q", len(raw)))
        framed.extend(raw)
    return bytes(framed)


def _test_owned_parameter_l2(current, initial) -> dict:
    if set(current) != set(initial):
        raise AssertionError("parameter telemetry fixture key mismatch")
    norm_sum = 0.0
    drift_sum = 0.0
    for name in sorted(current, key=lambda value: value.encode("utf-8")):
        current_values = current[name]
        initial_values = initial[name]
        if len(current_values) != len(initial_values):
            raise AssertionError("parameter telemetry fixture width mismatch")
        for current_value, initial_value in zip(
            current_values,
            initial_values,
            strict=True,
        ):
            if (
                type(current_value) is not float
                or type(initial_value) is not float
            ):
                raise AssertionError(
                    "parameter telemetry fixture requires binary32 floats"
                )
            norm_sum = norm_sum + current_value * current_value
            delta = current_value - initial_value
            drift_sum = drift_sum + delta * delta
    return {
        "drift_from_initial": math.sqrt(drift_sum),
        "norm": math.sqrt(norm_sum),
    }


def _checkpoint_parameter_l2_fixture(raw: bytes, initial_raw: bytes) -> dict:
    if len(raw) != 879900 or len(initial_raw) != 879900:
        raise AssertionError("checkpoint telemetry fixture width drifted")
    norm_sum = 0.0
    drift_sum = 0.0
    current_values = struct.iter_unpack("<f", raw)
    initial_values = struct.iter_unpack("<f", initial_raw)
    for (current_value,), (initial_value,) in zip(
        current_values,
        initial_values,
        strict=True,
    ):
        norm_sum = norm_sum + current_value * current_value
        delta = current_value - initial_value
        drift_sum = drift_sum + delta * delta
    return {
        "drift_from_initial": math.sqrt(drift_sum),
        "norm": math.sqrt(norm_sum),
    }


