def _canonical_tensor_sha256_from_raw_fixture(raw: bytes) -> str:
    if type(raw) is not bytes or len(raw) != 879900:
        raise AssertionError("smoke checkpoint is not the exact raw schema")
    framed = bytearray(b"f5-canonical-tensors-v1\0")
    framed.extend(struct.pack(">I", len(EXPECTED_TENSOR_SCHEMA)))
    offset = 0
    for name, shape, size in EXPECTED_TENSOR_SCHEMA:
        name_bytes = name.encode("ascii")
        dtype = b"float32-le"
        payload = raw[offset : offset + size]
        if len(payload) != size:
            raise AssertionError("smoke checkpoint tensor is truncated")
        if any(
            not math.isfinite(value[0])
            for value in struct.iter_unpack("<f", payload)
        ):
            raise AssertionError("smoke checkpoint tensor is non-finite")
        framed.extend(struct.pack(">I", len(name_bytes)))
        framed.extend(name_bytes)
        framed.extend(struct.pack(">I", len(dtype)))
        framed.extend(dtype)
        framed.extend(struct.pack(">I", len(shape)))
        for dimension in shape:
            framed.extend(struct.pack(">Q", dimension))
        framed.extend(struct.pack(">Q", len(payload)))
        framed.extend(payload)
        offset += size
    if offset != len(raw):
        raise AssertionError("smoke checkpoint has a trailing byte")
    return hashlib.sha256(framed).hexdigest()


def _cosine_schedule_fixture(
    *,
    base: float,
    floor_ratio: float,
    update_index: int,
    binary32_applied: bool,
) -> float:
    progress = update_index / 2956
    floor = base * floor_ratio
    value = floor + 0.5 * (base - floor) * (
        1.0 + math.cos(math.pi * progress)
    )
    return _binary32(value) if binary32_applied else value


