def _materialize_artifact_fixture(
    artifact_root: pathlib.Path,
    bundle: dict,
    *,
    post_verdict: bool,
) -> str | None:
    artifact_root.mkdir(parents=True, exist_ok=False)
    artifact_root.chmod(0o700)
    for relative in EXPECTED_SUBDIRECTORIES:
        directory = artifact_root / relative
        directory.mkdir(parents=True, exist_ok=False)
        directory.chmod(0o700)
    for relative, raw in bundle["payloads"].items():
        path = artifact_root / relative
        path.write_bytes(raw)
        path.chmod(0o600)
    evidence_path = artifact_root / "evidence-manifest.json"
    evidence_path.write_bytes(bundle["evidence_bytes"])
    evidence_path.chmod(0o600)
    if post_verdict:
        verdict_path = artifact_root / "verdict.json"
        verdict_path.write_bytes(bundle["verdict_bytes"])
        verdict_path.chmod(0o600)

    files = []
    directories = []
    if artifact_root.stat().st_mode & 0o777 != 0o700:
        raise AssertionError("positive artifact root mode drifted")
    for path in artifact_root.rglob("*"):
        relative = path.relative_to(artifact_root).as_posix()
        if path.is_symlink():
            raise AssertionError("positive artifact contains a symlink")
        if path.is_dir():
            directories.append(relative)
            if path.stat().st_mode & 0o777 != 0o700:
                raise AssertionError("positive artifact directory mode drifted")
        elif path.is_file():
            files.append(relative)
            metadata = path.stat()
            if metadata.st_nlink != 1 or metadata.st_mode & 0o777 != 0o600:
                raise AssertionError("positive artifact file identity drifted")
        else:
            raise AssertionError("positive artifact has unsupported entry")
    expected_files = [
        *_expected_payload_paths(),
        "evidence-manifest.json",
    ]
    if post_verdict:
        expected_files.append("verdict.json")
    if sorted(files) != sorted(expected_files):
        raise AssertionError("positive artifact file set drifted")
    if sorted(directories) != sorted(EXPECTED_SUBDIRECTORIES):
        raise AssertionError("positive artifact directory set drifted")
    if len(files) != (69 if post_verdict else 68):
        raise AssertionError("positive artifact file count drifted")
    if sys.platform == "darwin":
        phase = "post_verdict" if post_verdict else "pre_verdict"
        expected_links = EXPECTED_DIRECTORY_LINK_COUNTS[phase]
        for relative, expected in expected_links.items():
            directory = (
                artifact_root
                if relative == "."
                else artifact_root / relative
            )
            if directory.stat().st_nlink != expected:
                raise AssertionError(
                    "positive artifact directory link count drifted: "
                    + relative
                )
    return bundle["verdict_sha256"] if post_verdict else None


def _reseal_evidence_fixture(
    artifact_root: pathlib.Path,
    bundle: dict,
    *,
    path: str,
    raw: bytes,
    semantic_sha256: str | None = None,
    update_verdict: bool,
) -> str | None:
    payload_path = artifact_root / path
    payload_path.write_bytes(raw)
    payload_path.chmod(0o600)
    evidence = copy.deepcopy(bundle["evidence_manifest"])
    entry = next(
        item for item in evidence["payloads"] if item["path"] == path
    )
    entry["bytes"] = len(raw)
    entry["sha256"] = hashlib.sha256(raw).hexdigest()
    if semantic_sha256 is None:
        if path == "training-trace.jsonl":
            semantic_sha256 = hashlib.sha256(
                b"f5-training-trace-v1\0" + raw
            ).hexdigest()
        elif path.endswith(".f5w"):
            semantic_sha256 = (
                _canonical_tensor_sha256_from_raw_fixture(raw)
            )
        elif path.endswith(".bits"):
            raise AssertionError(
                "bitset reseal requires explicit framed semantic digest"
            )
        else:
            semantic_sha256 = hashlib.sha256(
                b"f5-canonical-json-v1\0" + raw
            ).hexdigest()
    entry["semantic_sha256"] = semantic_sha256
    evidence_bytes = _canonical_json_fixture(evidence)
    evidence_path = artifact_root / "evidence-manifest.json"
    evidence_path.write_bytes(evidence_bytes)
    evidence_path.chmod(0o600)
    if not update_verdict:
        return None
    verdict = copy.deepcopy(bundle["verdict"])
    verdict["evidence_manifest_sha256"] = hashlib.sha256(
        evidence_bytes
    ).hexdigest()
    verdict_bytes = _canonical_json_fixture(verdict)
    verdict_path = artifact_root / "verdict.json"
    verdict_path.write_bytes(verdict_bytes)
    verdict_path.chmod(0o600)
    return hashlib.sha256(verdict_bytes).hexdigest()


class _FakeCollector:
    def __init__(
        self,
        *,
        mode="training",
        matches=2048,
        timeline=None,
    ):
        fixture = _valid_transition_fixture(matches, mode=mode)
        self.mode = mode
        self.rewards = fixture["rewards"]
        self.terminals = fixture["terminals"]
        if mode == "training":
            self.tail_rewards = fixture["tail_rewards"]
            self.tail_terminals = fixture["tail_terminals"]
        else:
            self.pending_rewards = fixture["pending_rewards"]
            self.pending_terminals = fixture["pending_terminals"]
        self.env_logs = _valid_raw_log(matches)
        self.endpoint_checks = _endpoint_checks()
        self.events = [] if timeline is None else timeline
        self.parameters = b"parameters-before"
        self.optimizer_state = b"optimizer-before"
        self.epoch = 0
        self.global_step = 0
        self.accepted_global_agent_step = 0
        self.accepted_ledger = []
        self.checkpoints = {}
        self.discarded = False
        self.closed = False

    def rollouts(self):
        if self.discarded or self.closed:
            raise AssertionError("discarded collector was reused")
        self.events.append("rollouts")
        self.global_step += 32768
        return None

    def train(self):
        if self.discarded or self.closed:
            raise AssertionError("discarded collector reached optimizer")
        self.events.append("train")
        self.parameters = b"parameters-after"
        self.optimizer_state = b"optimizer-after"
        self.epoch += 1
        return {"loss": 0.0}

    def commit_accepted_trace(self, row):
        if self.discarded or self.closed:
            raise AssertionError("discarded collector reached commit")
        self.events.append("accepted-commit")
        self.accepted_ledger.append(copy.deepcopy(row))
        self.accepted_global_agent_step = self.epoch * 32768

    def discard(self):
        self.events.append("discard")
        self.discarded = True
        self.closed = True


class _FakeTensor:
    def __init__(
        self,
        shape,
        *,
        payload=None,
        dtype="float32",
        device="cpu",
        contiguous=True,
    ):
        self.shape = tuple(shape)
        self.payload = payload
        self.dtype = dtype
        self.device = device
        self.contiguous = contiguous

    def is_contiguous(self):
        return self.contiguous


class _FakePolicy:
    def __init__(self, *, mutate=None):
        state = {
            name: _FakeTensor(shape)
            for name, shape, _size in EXPECTED_TENSOR_SCHEMA
        }
        if mutate == "missing":
            state.pop(next(iter(state)))
        elif mutate == "extra":
            state["extra"] = _FakeTensor((1,))
        elif mutate == "shape":
            name = next(iter(state))
            state[name] = _FakeTensor((1,))
        elif mutate == "dtype":
            name = next(iter(state))
            state[name] = _FakeTensor(
                EXPECTED_TENSOR_SCHEMA[0][1],
                dtype="float64",
            )
        elif mutate == "device":
            name = next(iter(state))
            state[name] = _FakeTensor(
                EXPECTED_TENSOR_SCHEMA[0][1],
                device="cuda:0",
            )
        self._state = state
        self.loaded = None
        self.strict = None

    def state_dict(self):
        return self._state

    def load_state_dict(self, state, *, strict):
        self.loaded = state
        self.strict = strict
        return object()


def _ast_call_name(call):
    node = call.func
    parts = []
    while isinstance(node, ast.Attribute):
        parts.append(node.attr)
        node = node.value
    if isinstance(node, ast.Name):
        parts.append(node.id)
    else:
        return None
    return ".".join(reversed(parts))


def _test_stream_cap_namespace(
    source,
    *,
    filename="<stream-cap-synthetic>",
):
    _test_stream_cap_reject_module_global_mutation(source)
    namespace = {}
    exec(compile(source, filename, "exec"), namespace)
    return namespace


def _test_stream_cap_reject_module_global_mutation(source):
    tree = ast.parse(source)
    parent = {}
    for node in ast.walk(tree):
        for child in ast.iter_child_nodes(node):
            parent[child] = node

    def is_module_scoped(node):
        while node in parent:
            node = parent[node]
            if isinstance(
                node,
                (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda),
            ):
                return False
        return True

    for node in ast.walk(tree):
        if not isinstance(node, (ast.Attribute, ast.Subscript)) or not isinstance(
            node.ctx, (ast.Store, ast.Del)
        ):
            continue
        root = node.value
        while isinstance(root, (ast.Attribute, ast.Subscript)):
            root = root.value
        if (
            isinstance(root, ast.Name)
            and root.id in {"errno", "hashlib"}
            and is_module_scoped(node)
        ):
            raise AssertionError("module-global-attribute-mutation")
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not is_module_scoped(node):
            continue
        loaded_arguments = {
            child.id
            for argument in (
                list(node.args)
                + [keyword.value for keyword in node.keywords]
            )
            for child in ast.walk(argument)
            if isinstance(child, ast.Name)
            and isinstance(child.ctx, ast.Load)
        }
        if loaded_arguments & {"errno", "hashlib"}:
            raise AssertionError("module-global-call-argument")
    if any(
        isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id in {"errno", "hashlib"}
        and is_module_scoped(node)
        for node in ast.walk(tree)
    ):
        raise AssertionError("module-global-authority-alias")


# This contract models a resumable frame across descriptor reads and keeps the
# parser on the script-local operations adapter required by the outer-process
# import boundary.
_STREAM_CAP_REFERENCE_SOURCE = '''\
import errno
import hashlib

def measured_add(total, increment, cap):
    if type(total) is not int or type(increment) is not int or type(cap) is not int:
        raise ValueError("strict integer")
    if total < 0 or increment < 0 or cap < 0:
        raise ValueError("negative")
    prospective = total + increment
    if prospective > cap:
        raise ValueError("cap")
    return prospective

def _supervise_prepared_worker(operations, *, job, expected_sequence, deadline_ns):
    stdout_read, stdout_write = operations.make_pipe("stdout")
    stderr_read, stderr_write = operations.make_pipe("stderr")
    job_wire = operations.encode_job(job)
    operations.bind_request(job_wire)
    worker_kind = job["worker_kind"]
    if worker_kind == "training":
        payload_cap = 33554432
        wire_cap = 33587232
    if worker_kind == "evaluation":
        payload_cap = 8388608
        wire_cap = 8396808
    stderr_cap = 65536
    wire_total = 0
    payload_total = 0
    stderr_total = 0
    stdout_buffer = bytearray()
    stderr_retained = bytearray()
    active_frame = False
    declared_payload_bytes = 0
    spool = None
    raw_hasher = None
    stdout_eof = False
    while operations.more_stdout():
        try:
            stdout_chunk = operations.read_nonblocking(stdout_read, 65536)
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            continue
        if not stdout_chunk:
            operations.finish_stdout()
            stdout_eof = True
            break
        try:
            wire_total = measured_add(wire_total, len(stdout_chunk), wire_cap)
            stdout_buffer.extend(stdout_chunk)
            while True:
                if not active_frame:
                    if not operations.header_ready(stdout_buffer):
                        break
                    header = operations.take_header(stdout_buffer)
                    operations.validate_declared_frame(header, expected_sequence)
                    declared_payload_bytes = header["bytes"]
                    spool = operations.create_private_spool(
                        frame_index=header["frame_index"],
                        kind=header["kind"],
                        logical_name=header["logical_name"],
                    )
                    raw_hasher = hashlib.sha256()
                    active_frame = True
                while stdout_buffer and operations.payload_remaining(declared_payload_bytes):
                    payload_chunk = operations.take_payload(stdout_buffer, declared_payload_bytes)
                    if not payload_chunk:
                        raise RuntimeError("payload parser made no progress")
                    payload_total = measured_add(payload_total, len(payload_chunk), payload_cap)
                    raw_hasher.update(payload_chunk)
                    operations.write_private_spool(spool, payload_chunk)
                if operations.payload_remaining(declared_payload_bytes):
                    break
                operations.finish_frame(declared_payload_bytes, raw_hasher.hexdigest())
                active_frame = False
                declared_payload_bytes = 0
                spool = None
                raw_hasher = None
                if not stdout_buffer:
                    break
        except Exception:
            while operations.terminating_with_discard():
                try:
                    discarded_stdout_chunk = operations.read_nonblocking(stdout_read, 65536)
                except BlockingIOError as drain_error:
                    if drain_error.errno == errno.EAGAIN:
                        continue
                    break
                except Exception:
                    break
                if not discarded_stdout_chunk:
                    break
            raise
    if not stdout_eof:
        raise RuntimeError("stdout ended without descriptor EOF")
    while operations.more_stderr():
        try:
            stderr_chunk = operations.read_nonblocking(stderr_read, 65536)
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            continue
        if not stderr_chunk:
            break
        stderr_total = measured_add(stderr_total, len(stderr_chunk), stderr_cap)
        stderr_retained.extend(stderr_chunk)
    while operations.terminating_with_discard():
        try:
            discarded_stderr_chunk = operations.read_nonblocking(stderr_read, 65536)
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            continue
        if not discarded_stderr_chunk:
            break
    return wire_total, payload_total, stderr_total
'''


