def _test_hybrid_reactor_fixture_evidence(fixture):
    return {
        "expected_sequence": copy.deepcopy(
            fixture["expected_sequence"]
        ),
        "expected_sequence_identity": id(
            fixture["expected_sequence"]
        ),
        "frames": tuple(
            (
                copy.deepcopy(dict(frame["header"])),
                len(frame["payload"]),
                hashlib.sha256(frame["payload"]).hexdigest(),
                len(frame["wire"]),
                hashlib.sha256(frame["wire"]).hexdigest(),
            )
            for frame in fixture["frames"]
        ),
        "frame_identities": tuple(
            (
                id(frame),
                id(frame["header"]),
                id(frame["payload"]),
                id(frame["wire"]),
            )
            for frame in fixture["frames"]
        ),
        "headers": copy.deepcopy(fixture["headers"]),
        "job": copy.deepcopy(fixture["job"]),
        "job_identity": id(fixture["job"]),
        "job_wire": (
            id(fixture["job_wire"]),
            len(fixture["job_wire"]),
            hashlib.sha256(fixture["job_wire"]).hexdigest(),
        ),
        "payloads": tuple(
            (
                id(payload),
                len(payload),
                hashlib.sha256(payload).hexdigest(),
            )
            for payload in fixture["payloads"]
        ),
        "record": copy.deepcopy(fixture["record"]),
        "record_identity": id(fixture["record"]),
        "stdout": (
            id(fixture["stdout"]),
            len(fixture["stdout"]),
            hashlib.sha256(fixture["stdout"]).hexdigest(),
        ),
    }


class _PreparedWorkerSpool:
    def __init__(self, identity):
        self.identity = identity
        self.raw = bytearray()
        self.offset = 0
        self.closed = False


class _ExpectedPayloadVirtualSpool:
    """Immutable fixture-backed spool with exact write/read coverage proofs."""

    def __init__(self, identity, expected_payload):
        if type(expected_payload) is not bytes or not expected_payload:
            raise AssertionError("virtual spool payload is not immutable bytes")
        self.identity = identity
        self.expected_payload = expected_payload
        self.write_offset = 0
        self.write_chunk_sizes = []
        self.read_passes = []
        self.active_pass = None
        self.read_started = False
        self.closed = False
        self.close_count = 0


class _PreparedWorkerSupervisorDouble:
    """Deterministic OS reactor for both real prepared-worker supervisors."""

    def __init__(
        self,
        fixture,
        *,
        stdout_chunks=None,
        stderr_chunks=None,
        child_states=None,
        scripted_times=None,
        scripted_turns=None,
        fault_at=None,
        pre_latched_signal=None,
        keep_child_live_after_term=False,
        child_exit_at_ns=None,
        latch_after_stdout_read=None,
        guard_turn_exhaustion=False,
        runtime_scratch=None,
    ):
        self.fixture = fixture
        self.stdout_chunks = collections.deque(
            stdout_chunks
            if stdout_chunks is not None
            else [fixture["stdout"], _PIPE_EOF]
        )
        self.stderr_chunks = collections.deque(
            stderr_chunks
            if stderr_chunks is not None
            else [_PIPE_EOF]
        )
        self.child_states = collections.deque(
            child_states
            if child_states is not None
            else [None, ("exit", 0)]
        )
        self.scripted_times = collections.deque(
            scripted_times if scripted_times is not None else []
        )
        self.current_time_ns = 0
        self.scripted_turns = collections.deque(
            scripted_turns if scripted_turns is not None else []
        )
        self.fault_at = dict(fault_at or {})
        self.pre_latched_signal = pre_latched_signal
        self.keep_child_live_after_term = keep_child_live_after_term
        self.child_exit_at_ns = child_exit_at_ns
        self.latch_after_stdout_read = latch_after_stdout_read
        self.guard_turn_exhaustion = guard_turn_exhaustion
        self.events = []
        self.created_endpoints = set()
        self.closed_endpoints = set()
        self.close_counts = collections.Counter()
        self.read_observations = []
        self.signal_observations = []
        self.waits_ns = []
        self.spawn_calls = []
        self.input_bytes = bytearray()
        self.input_closed = False
        self.spools = []
        self.spool_writes = []
        self._worker_stream_oracle = _TestWorkerStreamOracle()
        self.signals = []
        self.reap_calls = 0
        self.postflight_jobs = []
        self.child = types.SimpleNamespace(pid=424242, pgid=424242)
        self._scratch_directory = None
        if runtime_scratch is None:
            self._scratch_directory = tempfile.TemporaryDirectory(
                prefix="f5-supervisor-runtime-"
            )
            scratch_root = pathlib.Path(
                self._scratch_directory.name
            ).resolve()
            self.runtime_scratch_owned = True
        else:
            scratch_root = pathlib.Path(runtime_scratch).resolve()
            scratch_root.mkdir(mode=0o700, parents=True, exist_ok=True)
            self.runtime_scratch_owned = False
        if (
            not scratch_root.is_dir()
            or scratch_root.is_symlink()
        ):
            raise AssertionError("supervisor scratch root is not a directory")
        scratch_root.chmod(0o700)
        self.runtime_scratch_root = scratch_root
        scratch = str(scratch_root)
        for component in ("home", "tmp", "cache"):
            directory = scratch_root / component
            directory.mkdir(mode=0o700, exist_ok=True)
            if not directory.is_dir() or directory.is_symlink():
                raise AssertionError(
                    "supervisor scratch child is not a directory"
                )
            directory.chmod(0o700)
        self.worker_environment = {
            key: value.replace("<private-runtime-scratch>", scratch)
            for key, value in EXPECTED_WORKER_ENVIRONMENT.items()
        }
        self.prepared_python_executable = (
            fixture["job"]["puffer_root"] + "/.venv/bin/python3.12"
        )

    def cleanup(self):
        if self._scratch_directory is not None:
            self._scratch_directory.cleanup()

    def _event(self, name, *details):
        self.events.append((name, *details))
        error = self.fault_at.pop(name, None)
        if error is not None:
            raise error

    def monotonic_ns(self):
        self._event("monotonic_ns")
        if not self.scripted_times:
            value = self.current_time_ns
        else:
            value = self.scripted_times.popleft()
        if type(value) is not int:
            raise AssertionError("fake monotonic clock emitted non-int")
        return value

    def first_signal_latched(self):
        self._event("first_signal_latched")
        return self.pre_latched_signal

    def make_pipe(self, logical_role):
        self._event("make_pipe", logical_role)
        endpoints = (
            f"{logical_role}-read",
            f"{logical_role}-write",
        )
        self.created_endpoints.update(endpoints)
        return endpoints

    def set_nonblocking(self, endpoint):
        self._event("set_nonblocking", endpoint)

    def close_endpoint(self, endpoint):
        self._event("close_endpoint", endpoint)
        self.closed_endpoints.add(endpoint)
        self.close_counts[endpoint] += 1
        if (
            str(endpoint).endswith("-write")
            and any(
                role in str(endpoint)
                for role in ("job", "stdin", "request", "input")
            )
        ):
            self.input_closed = True

    def write_nonblocking(self, endpoint, view):
        self._event("write_nonblocking", endpoint, len(view))
        if not (
            str(endpoint).endswith("-write")
            and any(
                role in str(endpoint)
                for role in ("job", "stdin", "request", "input")
            )
        ):
            raise AssertionError("worker input was written to wrong endpoint")
        raw = bytes(view)
        self.input_bytes.extend(raw)
        return len(raw)

    def encode_job(self, job):
        self._event("encode_job", job["worker_kind"])
        if job != self.fixture["job"]:
            raise AssertionError(
                "supervisor job serializer received mutated job"
            )
        return self.fixture["job_wire"]

    def bind_request(self, job_wire):
        self._event("bind_request", len(job_wire))
        return self._worker_stream_oracle.bind_request(job_wire)

    def header_ready(self, stdout_buffer):
        ready = self._worker_stream_oracle.header_ready(stdout_buffer)
        self._event("header_ready", ready, len(stdout_buffer))
        return ready

    def take_header(self, stdout_buffer):
        header = self._worker_stream_oracle.take_header(stdout_buffer)
        self._event("take_header", header["frame_index"])
        return header

    def validate_declared_frame(self, header, expected_sequence):
        self._worker_stream_oracle.validate_declared_frame(
            header, expected_sequence
        )
        self._event("validate_declared_frame", header["frame_index"])

    def payload_remaining(self, declared_payload_bytes):
        return self._worker_stream_oracle.payload_remaining(
            declared_payload_bytes
        )

    def take_payload(self, stdout_buffer, declared_payload_bytes):
        chunk = self._worker_stream_oracle.take_payload(
            stdout_buffer, declared_payload_bytes
        )
        self._event("take_payload", len(chunk))
        return chunk

    def finish_frame(self, declared_payload_bytes, observed_raw_sha256):
        self._worker_stream_oracle.finish_frame(
            declared_payload_bytes, observed_raw_sha256
        )
        self._event("finish_frame", declared_payload_bytes)

    def finish_stdout(self):
        self._worker_stream_oracle.finish_stdout()
        self._event("finish_stdout")

    def spawn_prepared_worker(self, **kwargs):
        self._event("spawn_prepared_worker")
        self.spawn_calls.append(dict(kwargs))
        return self.child

    def prove_worker_process_group(self, child):
        self._event("prove_worker_process_group", child.pid)
        return child.pgid

    def poll_child_nonblocking(self, child):
        self._event("poll_child_nonblocking", child.pid)
        if (
            self.child_exit_at_ns is not None
            and self.current_time_ns >= self.child_exit_at_ns
        ):
            state = ("exit", 0)
            self.events.append(("child_status", state))
            return state
        if not self.child_states:
            self.events.append(("child_status", None))
            return None
        if len(self.child_states) == 1:
            state = self.child_states[0]
        else:
            state = self.child_states.popleft()
        self.events.append(("child_status", state))
        return state

    def poll_ready(self, *, readable, writable, timeout_ns):
        self._event("poll_ready")
        if type(timeout_ns) is not int or not 0 <= timeout_ns <= 50_000_000:
            raise AssertionError("poll timeout escaped frozen 50ms slice")
        self.waits_ns.append(timeout_ns)
        if self.scripted_turns:
            turn = dict(self.scripted_turns.popleft())
            if "advance_to" in turn:
                self.current_time_ns = turn.pop("advance_to")
            for role, queue in (
                ("stdout", self.stdout_chunks),
                ("stderr", self.stderr_chunks),
            ):
                if turn.pop("release_" + role, False):
                    if queue and queue[0] is _PIPE_EAGAIN:
                        queue.popleft()
            return turn
        if self.guard_turn_exhaustion and not self.signals:
            raise AssertionError(
                "scripted readiness exhausted before supervisor selected "
                "and began terminating its immutable origin"
            )
        return {
            "stderr": bool(self.stderr_chunks),
            "stdout": bool(self.stdout_chunks),
            "writable": bool(writable) and not self.input_closed,
        }

    def read_nonblocking(self, endpoint, maximum_bytes):
        role = "stderr" if "stderr" in str(endpoint) else "stdout"
        self._event("read_nonblocking", role, maximum_bytes)
        if type(maximum_bytes) is not int or not 1 <= maximum_bytes <= 65536:
            raise AssertionError("read escaped frozen 65,536-byte chunk cap")
        queue = (
            self.stderr_chunks if role == "stderr" else self.stdout_chunks
        )
        if not queue:
            raise BlockingIOError(errno.EAGAIN, "scripted EAGAIN")
        value = queue.popleft()
        if value is _PIPE_EAGAIN:
            self.read_observations.append(
                (role, "EAGAIN", self.current_time_ns)
            )
            raise BlockingIOError(errno.EAGAIN, "scripted EAGAIN")
        if value is _PIPE_EOF:
            self.events.append(("read_result", role, 0))
            self.read_observations.append(
                (role, 0, self.current_time_ns)
            )
            return b""
        if isinstance(value, BaseException):
            raise value
        raw = bytes(value)
        if len(raw) > maximum_bytes:
            queue.appendleft(raw[maximum_bytes:])
            raw = raw[:maximum_bytes]
        if role == "stdout" and raw and self.latch_after_stdout_read:
            self.pre_latched_signal = self.latch_after_stdout_read
        self.events.append(("read_result", role, len(raw)))
        self.read_observations.append(
            (role, len(raw), self.current_time_ns)
        )
        return raw

    def create_private_spool(self, *, frame_index, kind, logical_name):
        self._event(
            "create_private_spool",
            frame_index,
            kind,
            logical_name,
        )
        spool = _PreparedWorkerSpool(
            (frame_index, kind, logical_name)
        )
        self.spools.append(spool)
        return spool

    def write_private_spool(self, spool, chunk):
        self._event("write_private_spool", spool.identity, len(chunk))
        if len(chunk) > 65536:
            raise AssertionError("spool write escaped frozen chunk cap")
        spool.raw.extend(chunk)
        self.spool_writes.append((spool.identity, len(chunk)))

    def rewind_private_spool(self, spool):
        self._event("rewind_private_spool", spool.identity)
        spool.offset = 0

    def read_private_spool(self, spool, maximum_bytes):
        self._event("read_private_spool", spool.identity, maximum_bytes)
        if not 1 <= maximum_bytes <= 65536:
            raise AssertionError("semantic spool read exceeded chunk cap")
        raw = bytes(spool.raw[spool.offset : spool.offset + maximum_bytes])
        spool.offset += len(raw)
        return raw

    def close_private_spool(self, spool):
        self._event("close_private_spool", spool.identity)
        spool.closed = True

    def run_outer_worker_postflight(self, *, job):
        self._event("run_outer_worker_postflight", job["worker_kind"])
        self.postflight_jobs.append(copy.deepcopy(job))

    def signal_worker_group(self, child, signo):
        self._event("signal_worker_group", child.pgid, signo)
        self.signals.append((child.pgid, signo))
        self.signal_observations.append(
            (child.pgid, signo, self.current_time_ns)
        )
        if signo == signal.SIGTERM and not self.keep_child_live_after_term:
            self.child_states.clear()
            self.child_states.append(("exit", 70))
        elif signo == signal.SIGKILL:
            self.child_states.clear()
            self.child_states.append(("signal", signal.SIGKILL))

    def reap_child_nonblocking(self, child):
        self._event("reap_child_nonblocking", child.pid)
        self.reap_calls += 1
        result = self.poll_child_nonblocking(child)
        self.events.append(
            ("reap_result", result, self.current_time_ns)
        )
        return result


class _ScriptedWorkerSupervisorMatrixDouble(
    _PreparedWorkerSupervisorDouble
):
    """Inert scripted extensions for precedence and job-write matrices."""

    def __init__(
        self,
        fixture,
        *,
        write_outcomes=(),
        readiness_anchor=None,
        signal_at_readiness=None,
        deadline_at_readiness_ns=None,
        signal_at_completion=None,
        deadline_at_completion_ns=None,
        signal_after_postflight=None,
        deadline_after_postflight_ns=None,
        postflight_exception=None,
        withhold_until_input_closed=False,
        **kwargs,
    ):
        super().__init__(fixture, **kwargs)
        self.write_outcomes = collections.deque(write_outcomes)
        self.write_offers = []
        self.write_results = []
        self.readiness_anchor = readiness_anchor
        self.readiness_anchor_reached = False
        self.signal_at_readiness = signal_at_readiness
        self.deadline_at_readiness_ns = deadline_at_readiness_ns
        self.signal_at_completion = signal_at_completion
        self.deadline_at_completion_ns = deadline_at_completion_ns
        self.signal_after_postflight = signal_after_postflight
        self.deadline_after_postflight_ns = deadline_after_postflight_ns
        self.postflight_exception = postflight_exception
        self.withhold_until_input_closed = withhold_until_input_closed
        self.input_close_events = []
        self.observed_eof_roles = set()
        self.observed_terminal_state = None
        self.completion_barrier_reached = False
        self.postflight_attempts = 0
        self.postflight_successful_returns = 0
        self.postflight_raised = []

    def _input_endpoint(self, endpoint):
        return (
            str(endpoint).endswith("-write")
            and any(
                role in str(endpoint)
                for role in ("job", "stdin", "request", "input")
            )
        )

    def _maybe_mark_completion_barrier(self):
        if (
            self.completion_barrier_reached
            or self.observed_eof_roles != {"stderr", "stdout"}
            or self.observed_terminal_state is None
        ):
            return
        self.completion_barrier_reached = True
        self._event("semantic_anchor", "completion-barrier-reached")
        if self.signal_at_completion is not None:
            self.pre_latched_signal = self.signal_at_completion
        if self.deadline_at_completion_ns is not None:
            self.current_time_ns = self.deadline_at_completion_ns

    def close_endpoint(self, endpoint):
        super().close_endpoint(endpoint)
        if self._input_endpoint(endpoint):
            self.input_close_events.append(endpoint)

    def write_nonblocking(self, endpoint, view):
        self._event("write_nonblocking", endpoint, len(view))
        if not self._input_endpoint(endpoint):
            raise AssertionError("scripted job write used wrong endpoint")
        offered = bytes(view)
        if not offered:
            raise AssertionError("scripted job write offered empty suffix")
        self.write_offers.append(offered)
        outcome = (
            self.write_outcomes.popleft()
            if self.write_outcomes
            else len(offered)
        )
        if outcome is _PIPE_EAGAIN:
            self.write_results.append("EAGAIN")
            raise BlockingIOError(errno.EAGAIN, "scripted job EAGAIN")
        if isinstance(outcome, BaseException):
            self.write_results.append(
                (type(outcome).__name__, getattr(outcome, "errno", None))
            )
            raise outcome
        if (
            type(outcome) is not int
            or not 0 <= outcome <= len(offered)
        ):
            raise AssertionError("scripted job write result is invalid")
        self.input_bytes.extend(offered[:outcome])
        self.write_results.append(outcome)
        return outcome

    def poll_ready(self, *, readable, writable, timeout_ns):
        ready = super().poll_ready(
            readable=readable,
            writable=writable,
            timeout_ns=timeout_ns,
        )
        if (
            self.readiness_anchor is not None
            and self.input_closed
            and not self.readiness_anchor_reached
        ):
            self.readiness_anchor_reached = True
            self._event("semantic_anchor", self.readiness_anchor)
            if self.signal_at_readiness is not None:
                self.pre_latched_signal = self.signal_at_readiness
            if self.deadline_at_readiness_ns is not None:
                self.current_time_ns = self.deadline_at_readiness_ns
        if self.withhold_until_input_closed and not self.input_closed:
            ready = dict(ready)
            ready["stderr"] = False
            ready["stdout"] = False
        return ready

    def poll_child_nonblocking(self, child):
        if self.readiness_anchor is not None and not (
            self.readiness_anchor_reached
        ):
            self._event("poll_child_nonblocking", child.pid)
            self.events.append(("child_status", None))
            return None
        if self.withhold_until_input_closed and not self.input_closed:
            self._event("poll_child_nonblocking", child.pid)
            self.events.append(("child_status", None))
            return None
        result = super().poll_child_nonblocking(child)
        if result is not None:
            self.observed_terminal_state = result
            self._maybe_mark_completion_barrier()
        return result

    def read_nonblocking(self, endpoint, maximum_bytes):
        if self.withhold_until_input_closed and not self.input_closed:
            raise AssertionError("worker output preceded complete job input")
        role = "stderr" if "stderr" in str(endpoint) else "stdout"
        result = super().read_nonblocking(endpoint, maximum_bytes)
        if result == b"":
            self.observed_eof_roles.add(role)
            self._maybe_mark_completion_barrier()
        return result

    def run_outer_worker_postflight(self, *, job):
        self._event("run_outer_worker_postflight", job["worker_kind"])
        self.postflight_jobs.append(copy.deepcopy(job))
        self.postflight_attempts += 1
        self._event("postflight_attempt", job["worker_kind"])
        if self.postflight_exception is not None:
            error = self.postflight_exception
            self.postflight_exception = None
            raised = (type(error), getattr(error, "errno", None))
            self.postflight_raised.append(raised)
            self._event(
                "postflight_raise",
                raised[0].__name__,
                raised[1],
            )
            raise error
        self.postflight_successful_returns += 1
        self._event("semantic_anchor", "postflight-returned")
        if self.signal_after_postflight is not None:
            self.pre_latched_signal = self.signal_after_postflight
        if self.deadline_after_postflight_ns is not None:
            self.current_time_ns = self.deadline_after_postflight_ns


class _StreamCapWorkerSupervisorDouble(
    _PreparedWorkerSupervisorDouble
):
    """Inert read-order witness for deterministic stream-cap contracts."""

    def __init__(
        self,
        fixture,
        *,
        withhold_stdout_until_signal=False,
        **kwargs,
    ):
        super().__init__(fixture, **kwargs)
        self.withhold_stdout_until_signal = withhold_stdout_until_signal
        self.ready_turn = 0
        self.read_requests = []
        self.read_returns = []

    def poll_ready(self, *, readable, writable, timeout_ns):
        self.ready_turn += 1
        ready = super().poll_ready(
            readable=readable,
            writable=writable,
            timeout_ns=timeout_ns,
        )
        if self.withhold_stdout_until_signal and not self.signals:
            ready = dict(ready)
            ready["stdout"] = False
        return ready

    def read_nonblocking(self, endpoint, maximum_bytes):
        role = "stderr" if "stderr" in str(endpoint) else "stdout"
        self.read_requests.append(
            (self.ready_turn, role, maximum_bytes)
        )
        try:
            raw = super().read_nonblocking(endpoint, maximum_bytes)
        except BlockingIOError as error:
            if error.errno == errno.EAGAIN:
                self.read_returns.append(
                    (self.ready_turn, role, "EAGAIN")
                )
            raise
        self.read_returns.append(
            (self.ready_turn, role, len(raw))
        )
        return raw


class _RealKernelPipeSupervisorDouble(
    _PreparedWorkerSupervisorDouble
):
    """Real-kernel-pipe coverage for the supervisor loop, not its adapter."""

    _FILL_BYTE = b"\xa5"
    _MAX_FILL_ITERATIONS = 1_000_000
    _REAL_READ_CHUNK = 4096

    def __init__(
        self,
        fixture,
        *,
        real_role,
        job_mode=None,
        deadline_transition_ns=None,
        **kwargs,
    ):
        if real_role not in {"job", "stdout"}:
            raise AssertionError("unsupported real kernel pipe role")
        if job_mode not in {None, "deadline", "recover"}:
            raise AssertionError("unsupported real job pipe mode")
        if (real_role == "job") != (job_mode is not None):
            raise AssertionError("real job mode/role mismatch")
        super().__init__(fixture, **kwargs)
        if real_role == "stdout":
            self.stdout_chunks = collections.deque()
        self.real_role = real_role
        self.job_mode = job_mode
        self.deadline_transition_ns = deadline_transition_ns
        self.real_pairs = {}
        self.endpoint_roles = {}
        self.production_fds = set()
        self.production_original_flags = {}
        self.production_nonblocking_calls = []
        self.production_cleanup_leaks = []
        self.peer_fds = set()
        self.peer_saved_flags = {}
        self.peer_close_counts = collections.Counter()
        self.peer_flag_restorations = []
        self.child_peer_fd = None
        self.actual_eagain = []
        self.real_ready_observations = []
        self.job_stale_readiness_created = False
        self.job_filler_bytes = 0
        self.job_filler_write_sha256 = hashlib.sha256()
        self.job_filler_read_sha256 = hashlib.sha256()
        self.job_filler_drained = False
        self.job_write_offers = []
        self.job_write_results = []
        self.job_peer_bytes = bytearray()
        self.job_peer_eof = False
        self.stdout_source_offset = 0
        self.stdout_pump_writes = []
        self.stdout_pump_phases = 0
        self.stdout_pump_eagain = 0
        self.stdout_one_byte_eagain_events = []
        self.stdout_first_read_event = None
        self.stdout_ready_pending = False
        self.stdout_read_bytes = 0
        self.stdout_read_sha256 = hashlib.sha256()
        self.stdout_read_requests = []
        self.stdout_read_results = []
        self.stdout_read_eof = False

    @staticmethod
    def _logical_role(logical_role):
        text = str(logical_role).lower()
        if "stdout" in text and "stderr" not in text:
            return "stdout"
        if "stderr" in text and "stdout" not in text:
            return "stderr"
        if any(
            component in text
            for component in ("input", "job", "request", "stdin")
        ):
            return "job"
        return None

    @staticmethod
    def _fd_requested(collection, descriptor):
        if collection is None:
            return False
        if collection == descriptor:
            return True
        try:
            return descriptor in collection
        except TypeError:
            return False

    @staticmethod
    def _fd_is_open(descriptor):
        try:
            fcntl.fcntl(descriptor, fcntl.F_GETFD)
        except OSError as error:
            if error.errno == errno.EBADF:
                return False
            raise
        return True

    def _assert_nonblocking(self, descriptor):
        flags = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        if not flags & os.O_NONBLOCK:
            raise AssertionError("real pipe syscall lacked O_NONBLOCK")
        return flags

    def _set_peer_nonblocking(self, descriptor):
        saved = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        self.peer_saved_flags[descriptor] = saved
        fcntl.fcntl(
            descriptor,
            fcntl.F_SETFL,
            saved | os.O_NONBLOCK,
        )
        observed = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        if (
            not observed & os.O_NONBLOCK
            or observed & ~os.O_NONBLOCK
            != saved & ~os.O_NONBLOCK
        ):
            raise AssertionError("peer nonblocking flag mutation drifted")

    def _close_peer(self, descriptor):
        if descriptor not in self.peer_fds:
            raise AssertionError("unknown real-pipe peer descriptor")
        if not self._fd_is_open(descriptor):
            raise AssertionError("real-pipe peer closed before ownership")
        saved = self.peer_saved_flags[descriptor]
        before_restore = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        target = (
            before_restore & ~os.O_NONBLOCK
        ) | (saved & os.O_NONBLOCK)
        fcntl.fcntl(descriptor, fcntl.F_SETFL, target)
        observed = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        self.peer_flag_restorations.append(
            (
                descriptor,
                saved,
                before_restore,
                target,
                observed,
            )
        )
        if (
            observed != target
            or observed & os.O_NONBLOCK
            != saved & os.O_NONBLOCK
            or observed & saved != saved
        ):
            raise AssertionError("real-pipe peer flags were not restored")
        os.close(descriptor)
        self.peer_close_counts[descriptor] += 1
        if self._fd_is_open(descriptor):
            raise AssertionError("real-pipe peer survived close")

    def make_pipe(self, logical_role):
        role = self._logical_role(logical_role)
        if role != self.real_role:
            return super().make_pipe(logical_role)
        self._event("make_pipe", logical_role)
        if role in self.real_pairs:
            raise AssertionError("real pipe role was created twice")
        read_fd, write_fd = os.pipe()
        self.real_pairs[role] = (read_fd, write_fd)
        self.endpoint_roles[read_fd] = (role, "read")
        self.endpoint_roles[write_fd] = (role, "write")
        self.production_fds.update((read_fd, write_fd))
        self.created_endpoints.update((read_fd, write_fd))
        return read_fd, write_fd

    def set_nonblocking(self, endpoint):
        if endpoint not in self.production_fds:
            return super().set_nonblocking(endpoint)
        self._event("set_nonblocking", endpoint)
        saved = fcntl.fcntl(endpoint, fcntl.F_GETFL)
        if endpoint in self.production_original_flags:
            raise AssertionError("production endpoint set nonblocking twice")
        self.production_original_flags[endpoint] = saved
        fcntl.fcntl(
            endpoint,
            fcntl.F_SETFL,
            saved | os.O_NONBLOCK,
        )
        observed = fcntl.fcntl(endpoint, fcntl.F_GETFL)
        if (
            not observed & os.O_NONBLOCK
            or observed & ~os.O_NONBLOCK
            != saved & ~os.O_NONBLOCK
        ):
            raise AssertionError(
                "production nonblocking flag mutation drifted"
            )
        self.production_nonblocking_calls.append(endpoint)

    def _fill_job_pipe_to_one_byte_eagain(self):
        write_fd = self.real_pairs["job"][1]
        self._assert_nonblocking(write_fd)
        offer = 4096
        for _iteration in range(self._MAX_FILL_ITERATIONS):
            raw = self._FILL_BYTE * offer
            try:
                written = os.write(write_fd, raw)
            except BlockingIOError as error:
                if error.errno != errno.EAGAIN:
                    raise
                self.actual_eagain.append(
                    ("harness-fill", "job", offer)
                )
                if offer == 1:
                    return
                offer = max(1, offer // 2)
                continue
            if type(written) is not int or not 1 <= written <= offer:
                raise AssertionError("real job filler write was invalid")
            self.job_filler_bytes += written
            self.job_filler_write_sha256.update(raw[:written])
        raise AssertionError("real job pipe fill exceeded iteration cap")

    def _drain_job_filler(self):
        if self.job_filler_drained:
            return
        peer = self.child_peer_fd
        self._assert_nonblocking(peer)
        remaining = self.job_filler_bytes
        for _iteration in range(self._MAX_FILL_ITERATIONS):
            if remaining == 0:
                break
            raw = os.read(peer, min(65536, remaining))
            if not raw:
                raise AssertionError("real job filler reached early EOF")
            if raw != self._FILL_BYTE * len(raw):
                raise AssertionError("real job filler bytes drifted")
            remaining -= len(raw)
            self.job_filler_read_sha256.update(raw)
        else:
            raise AssertionError("real job filler drain exceeded cap")
        if remaining:
            raise AssertionError("real job filler drain was incomplete")
        try:
            os.read(peer, 1)
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            self.actual_eagain.append(
                ("harness-drain", "job", 1)
            )
        else:
            raise AssertionError(
                "real job filler drain did not reach EAGAIN"
            )
        if (
            self.job_filler_read_sha256.hexdigest()
            != self.job_filler_write_sha256.hexdigest()
        ):
            raise AssertionError("real job filler digest drifted")
        self.job_filler_drained = True

    def _drain_job_wire(self, *, require_eof):
        peer = self.child_peer_fd
        self._assert_nonblocking(peer)
        for _iteration in range(self._MAX_FILL_ITERATIONS):
            try:
                raw = os.read(peer, 65536)
            except BlockingIOError as error:
                if error.errno != errno.EAGAIN:
                    raise
                self.actual_eagain.append(
                    ("worker-read", "job", 65536)
                )
                if require_eof:
                    raise AssertionError(
                        "real job input stayed open after supervisor close"
                    )
                return
            if not raw:
                self.job_peer_eof = True
                break
            self.job_peer_bytes.extend(raw)
        else:
            raise AssertionError("real job relay exceeded iteration cap")
        if self.job_peer_eof:
            expected_wire = (
                self.fixture["job_wire"]
                if self.job_mode == "recover"
                else b""
            )
            if bytes(self.job_peer_bytes) != expected_wire:
                raise AssertionError("real job relay bytes drifted")
            return
        if require_eof:
            raise AssertionError("real job relay did not observe EOF")

    def _pump_stdout_until_blocked(self):
        peer = self.child_peer_fd
        if peer is None or not self._fd_is_open(peer):
            return
        self._assert_nonblocking(peer)
        source = self.fixture["stdout"]
        wrote = False
        offer = 65536
        for _iteration in range(self._MAX_FILL_ITERATIONS):
            if self.stdout_source_offset == len(source):
                self._close_peer(peer)
                return
            size = min(
                offer,
                len(source) - self.stdout_source_offset,
            )
            chunk = source[
                self.stdout_source_offset :
                self.stdout_source_offset + size
            ]
            try:
                written = os.write(peer, chunk)
            except BlockingIOError as error:
                if error.errno != errno.EAGAIN:
                    raise
                self.actual_eagain.append(
                    ("worker-write", "stdout", size)
                )
                self.stdout_pump_eagain += 1
                if size == 1:
                    self.stdout_one_byte_eagain_events.append(
                        len(self.events)
                    )
                    if wrote:
                        self.stdout_pump_phases += 1
                    return
                offer = max(1, size // 2)
                continue
            if type(written) is not int or not 1 <= written <= size:
                raise AssertionError("real stdout relay write invalid")
            wrote = True
            self.stdout_pump_writes.append(written)
            self.stdout_source_offset += written
            offer = 65536
        raise AssertionError("real stdout relay exceeded iteration cap")

    def spawn_prepared_worker(self, **kwargs):
        child = super().spawn_prepared_worker(**kwargs)
        child_endpoint = (
            kwargs["stdin"]
            if self.real_role == "job"
            else kwargs["stdout"]
        )
        if (
            child_endpoint not in self.production_fds
            or self.child_peer_fd is not None
        ):
            raise AssertionError("real child endpoint binding drifted")
        peer = os.dup(child_endpoint)
        self.child_peer_fd = peer
        self.peer_fds.add(peer)
        self._set_peer_nonblocking(peer)
        if self.real_role == "job":
            self._assert_nonblocking(self.real_pairs["job"][1])
        return child

    def close_endpoint(self, endpoint):
        if endpoint not in self.production_fds:
            super().close_endpoint(endpoint)
            if (
                self.real_role == "stdout"
                and self.input_closed
                and self.stdout_source_offset == 0
            ):
                self._pump_stdout_until_blocked()
            return
        self._event("close_endpoint", endpoint)
        if endpoint in self.closed_endpoints:
            raise AssertionError("real production endpoint closed twice")
        if not self._fd_is_open(endpoint):
            raise AssertionError("real production endpoint was already closed")
        role, end = self.endpoint_roles[endpoint]
        if (
            role == "job"
            and end == "write"
            and not self.job_filler_drained
        ):
            self._drain_job_filler()
        os.close(endpoint)
        self.closed_endpoints.add(endpoint)
        self.close_counts[endpoint] += 1
        if role == "job" and end == "write":
            self.input_closed = True
            self._drain_job_wire(require_eof=True)

    def write_nonblocking(self, endpoint, view):
        if endpoint not in self.production_fds:
            return super().write_nonblocking(endpoint, view)
        role, end = self.endpoint_roles[endpoint]
        if role != "job" or end != "write":
            raise AssertionError("real supervisor write used wrong endpoint")
        self._event("write_nonblocking", endpoint, len(view))
        self._assert_nonblocking(endpoint)
        offered = bytes(view)
        if not offered:
            raise AssertionError("real supervisor offered empty job suffix")
        self.job_write_offers.append(offered)
        try:
            written = os.write(endpoint, offered)
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            self.actual_eagain.append(
                ("supervisor-write", "job", len(offered))
            )
            self.job_write_results.append("EAGAIN")
            if self.job_mode == "deadline":
                self.current_time_ns = self.deadline_transition_ns
            raise
        if type(written) is not int or not 1 <= written <= len(offered):
            raise AssertionError("real supervisor job write invalid")
        self.job_write_results.append(written)
        return written

    def poll_ready(self, *, readable, writable, timeout_ns):
        self._event("poll_ready")
        if type(timeout_ns) is not int or not 0 <= timeout_ns <= 50_000_000:
            raise AssertionError("real poll timeout escaped 50ms slice")
        if self.scripted_turns:
            raise AssertionError("real pipe double received scripted turns")
        self.waits_ns.append(timeout_ns)
        ready = {
            "stderr": bool(self.stderr_chunks),
            "stdout": bool(self.stdout_chunks),
            "writable": bool(writable) and not self.input_closed,
        }
        if self.real_role == "job":
            if self.input_closed:
                if not self.job_peer_eof:
                    raise AssertionError(
                        "real job input closed without peer EOF"
                    )
                ready["writable"] = False
                self.real_ready_observations.append(
                    ("job", False, self.current_time_ns)
                )
                return ready
            write_fd = self.real_pairs["job"][1]
            requested = self._fd_requested(writable, write_fd)
            _reads, writes, _errors = select.select(
                [],
                [write_fd] if requested else [],
                [],
                0,
            )
            if not self.job_stale_readiness_created:
                if write_fd not in writes:
                    raise AssertionError(
                        "fresh real job pipe was not writable"
                    )
                self._fill_job_pipe_to_one_byte_eagain()
                self.job_stale_readiness_created = True
                ready["writable"] = True
            else:
                if self.job_mode == "recover" and not (
                    self.job_filler_drained
                ):
                    self._drain_job_filler()
                if self.job_filler_drained:
                    self._drain_job_wire(require_eof=False)
                _reads, writes, _errors = select.select(
                    [],
                    [write_fd] if requested else [],
                    [],
                    0,
                )
                ready["writable"] = write_fd in writes
            if not self.job_peer_eof:
                ready["stderr"] = False
                ready["stdout"] = False
            self.real_ready_observations.append(
                ("job", ready["writable"], self.current_time_ns)
            )
            return ready
        if self.stdout_ready_pending:
            raise AssertionError(
                "supervisor repolled before draining stdout to EAGAIN/EOF"
            )
        if self.input_closed:
            self._pump_stdout_until_blocked()
        read_fd = self.real_pairs["stdout"][0]
        requested = self._fd_requested(readable, read_fd)
        reads, _writes, _errors = select.select(
            [read_fd] if requested else [],
            [],
            [],
            0,
        )
        ready["stdout"] = read_fd in reads
        self.stdout_ready_pending = ready["stdout"]
        self.real_ready_observations.append(
            ("stdout", ready["stdout"], self.current_time_ns)
        )
        return ready

    def read_nonblocking(self, endpoint, maximum_bytes):
        if endpoint not in self.production_fds:
            return super().read_nonblocking(endpoint, maximum_bytes)
        role, end = self.endpoint_roles[endpoint]
        if role != "stdout" or end != "read":
            raise AssertionError("real supervisor read used wrong endpoint")
        self._event("read_nonblocking", "stdout", maximum_bytes)
        if self.stdout_first_read_event is None:
            self.stdout_first_read_event = len(self.events) - 1
        if (
            type(maximum_bytes) is not int
            or not 1 <= maximum_bytes <= 65536
        ):
            raise AssertionError("real stdout read escaped chunk cap")
        self._assert_nonblocking(endpoint)
        self.stdout_read_requests.append(maximum_bytes)
        try:
            raw = os.read(
                endpoint,
                min(maximum_bytes, self._REAL_READ_CHUNK),
            )
        except BlockingIOError as error:
            if error.errno != errno.EAGAIN:
                raise
            self.actual_eagain.append(
                ("supervisor-read", "stdout", maximum_bytes)
            )
            self.stdout_read_results.append("EAGAIN")
            self.stdout_ready_pending = False
            raise
        self.stdout_read_results.append(len(raw))
        self.read_observations.append(
            ("stdout", len(raw), self.current_time_ns)
        )
        self.events.append(("read_result", "stdout", len(raw)))
        if raw:
            self.stdout_read_bytes += len(raw)
            self.stdout_read_sha256.update(raw)
        else:
            self.stdout_read_eof = True
            self.stdout_ready_pending = False
        return raw

    def poll_child_nonblocking(self, child):
        if (
            self.real_role == "job"
            and not self.job_peer_eof
        ) or (
            self.real_role == "stdout"
            and not self.stdout_read_eof
        ):
            self._event("poll_child_nonblocking", child.pid)
            self.events.append(("child_status", None))
            return None
        return super().poll_child_nonblocking(child)

    def cleanup(self):
        for descriptor in tuple(self.peer_fds):
            if self._fd_is_open(descriptor):
                self._close_peer(descriptor)
        for descriptor in tuple(self.production_fds):
            if self._fd_is_open(descriptor):
                self.production_cleanup_leaks.append(descriptor)
                os.close(descriptor)
        super().cleanup()


class _ExpectedPayloadVirtualSpoolSupervisorDouble(
    _PreparedWorkerSupervisorDouble
):
    """Use virtual spools only for the seven immutable training payloads."""

    def __init__(self, fixture, **kwargs):
        super().__init__(fixture, **kwargs)
        frames = fixture["frames"]
        if len(frames) != 8:
            raise AssertionError("virtual training frame count drifted")
        expected = {}
        for frame_index, frame in enumerate(frames[:7]):
            header = frame["header"]
            identity = (
                header["frame_index"],
                header["kind"],
                header["logical_name"],
            )
            if header["frame_index"] != frame_index or identity in expected:
                raise AssertionError("virtual spool identity drifted")
            expected[identity] = frame["payload"]
        self.virtual_expected_payloads = types.MappingProxyType(expected)
        final_header = frames[7]["header"]
        self.materialized_identity = (
            final_header["frame_index"],
            final_header["kind"],
            final_header["logical_name"],
        )
        self.created_spool_identities = set()

    def create_private_spool(self, *, frame_index, kind, logical_name):
        identity = (frame_index, kind, logical_name)
        self._event(
            "create_private_spool",
            frame_index,
            kind,
            logical_name,
        )
        if identity in self.created_spool_identities:
            raise AssertionError("spool identity was reused")
        self.created_spool_identities.add(identity)
        if identity in self.virtual_expected_payloads:
            spool = _ExpectedPayloadVirtualSpool(
                identity,
                self.virtual_expected_payloads[identity],
            )
        elif identity == self.materialized_identity:
            spool = _PreparedWorkerSpool(identity)
        else:
            raise AssertionError("unexpected training spool identity")
        self.spools.append(spool)
        return spool

    def write_private_spool(self, spool, chunk):
        if not isinstance(spool, _ExpectedPayloadVirtualSpool):
            return super().write_private_spool(spool, chunk)
        self._event("write_private_spool", spool.identity, len(chunk))
        if spool.closed or spool.read_started:
            raise AssertionError("virtual spool write followed read or close")
        if not 1 <= len(chunk) <= 65536:
            raise AssertionError("virtual spool write escaped exact chunk cap")
        raw = bytes(chunk)
        end = spool.write_offset + len(chunk)
        if end > len(spool.expected_payload):
            raise AssertionError("virtual spool write overflowed payload")
        if raw != spool.expected_payload[spool.write_offset : end]:
            raise AssertionError("virtual spool write mismatched exact prefix")
        spool.write_offset = end
        spool.write_chunk_sizes.append(len(chunk))
        self.spool_writes.append((spool.identity, len(chunk)))

    def rewind_private_spool(self, spool):
        if not isinstance(spool, _ExpectedPayloadVirtualSpool):
            return super().rewind_private_spool(spool)
        self._event("rewind_private_spool", spool.identity)
        if spool.closed:
            raise AssertionError("virtual spool rewind followed close")
        if spool.write_offset != len(spool.expected_payload):
            raise AssertionError("virtual spool read preceded full write")
        if (
            spool.active_pass is not None
            and spool.read_passes[spool.active_pass]["bytes"]
            != len(spool.expected_payload)
        ):
            raise AssertionError("virtual spool rewound an incomplete pass")
        spool.read_started = True
        spool.read_passes.append({"bytes": 0, "eof": False, "chunks": []})
        spool.active_pass = len(spool.read_passes) - 1

    def read_private_spool(self, spool, maximum_bytes):
        if not isinstance(spool, _ExpectedPayloadVirtualSpool):
            return super().read_private_spool(spool, maximum_bytes)
        self._event("read_private_spool", spool.identity, maximum_bytes)
        if (
            spool.closed
            or spool.active_pass is None
            or type(maximum_bytes) is not int
            or not 1 <= maximum_bytes <= 65536
        ):
            raise AssertionError("virtual spool read state or cap drifted")
        read_pass = spool.read_passes[spool.active_pass]
        if read_pass["eof"]:
            raise AssertionError("virtual spool returned EOF twice in a pass")
        offset = read_pass["bytes"]
        if offset > spool.write_offset:
            raise AssertionError("virtual spool served unwritten bytes")
        if offset == spool.write_offset:
            if offset != len(spool.expected_payload):
                raise AssertionError("virtual spool reached premature EOF")
            read_pass["eof"] = True
            return b""
        end = min(offset + maximum_bytes, spool.write_offset)
        raw = spool.expected_payload[offset:end]
        if not raw or len(raw) > maximum_bytes:
            raise AssertionError("virtual spool emitted invalid read chunk")
        read_pass["bytes"] = end
        read_pass["chunks"].append(len(raw))
        return raw

    def close_private_spool(self, spool):
        if not isinstance(spool, _ExpectedPayloadVirtualSpool):
            return super().close_private_spool(spool)
        self._event("close_private_spool", spool.identity)
        if spool.closed or spool.close_count:
            raise AssertionError("virtual spool closed more than once")
        expected_bytes = len(spool.expected_payload)
        if (
            spool.write_offset != expected_bytes
            or not spool.read_started
            or not spool.read_passes
            or any(
                read_pass["bytes"] != expected_bytes
                for read_pass in spool.read_passes
            )
        ):
            raise AssertionError("virtual spool closed without exact passes")
        spool.closed = True
        spool.close_count = 1


class _RealKernelTrainingPipeSupervisorDouble(
    _ExpectedPayloadVirtualSpoolSupervisorDouble,
    _RealKernelPipeSupervisorDouble,
):
    """Combine immutable training spools with the real stdout pipe."""


class _FinalConsumerPhaseProbe:
    def __init__(self, events, *, fail_marker=False):
        self.events = events
        self.fail_marker = fail_marker

    def mark_preflight_complete(self, context):
        self.events.append(("marker", context))
        if self.fail_marker:
            raise _InjectedPublicationFailure("marker")


class _AuthenticatedProtocolProbe:
    def __init__(self, events, *, result=True, fail=False):
        self.events = events
        self.result = result
        self.fail = fail

    def validate_final_evidence(
        self,
        artifact_root,
        expected_verdict_sha256,
    ):
        self.events.append(
            (
                "validate_final_evidence",
                artifact_root,
                expected_verdict_sha256,
            )
        )
        if self.fail:
            raise _InjectedPublicationFailure("validator")
        return self.result


class _EventRecorder:
    OPERATIONS = frozenset()

    def __init__(self, *, fail_at=None):
        self.events = []
        self.calls = []
        self.fail_at = fail_at

    def _record(self, name, *args, **kwargs):
        self.events.append(name)
        self.calls.append((name, args, kwargs))
        if self.fail_at == name:
            raise _InjectedPublicationFailure(name)
        return None

    def __getattr__(self, name):
        if name not in self.OPERATIONS:
            raise AttributeError(name)

        def operation(*args, **kwargs):
            return self._record(name, *args, **kwargs)

        return operation


class _FakeLeafPublicationIO(_EventRecorder):
    PRECOMMIT = (
        "validate_payload_semantics",
        "create_temporary_new",
        "fchmod_temporary_0600",
        "require_temporary_no_acl",
        "write_all",
        "flush_temporary",
        "fsync_temporary_file",
        "validate_parent_path_before",
        "require_destination_absent_nofollow",
        "validate_source_name_identity",
        "rename_exclusive",
    )
    POSTCOMMIT = (
        "validate_parent_path_after",
        "reopen_destination_nofollow",
        "validate_destination_identity",
        "require_destination_no_acl",
        "fsync_containing_directory",
    )
    OPERATIONS = frozenset(
        (*PRECOMMIT, *POSTCOMMIT, "validate_checkpoint_semantics")
    )

    def __init__(
        self,
        kind,
        *,
        fail_at=None,
        destination_kind=None,
        race_at_rename=False,
        race_kind=None,
    ):
        super().__init__(fail_at=fail_at)
        if kind not in {"payload", "checkpoint"}:
            raise AssertionError(kind)
        self.kind = kind
        self.source_identity = (
            "private-temporary",
            31,
            41,
            0o100600,
            1,
            879900 if kind == "checkpoint" else 17,
        )
        self.destination_identity = None
        self.destination_kind = destination_kind
        self.foreign_destination = (
            None
            if destination_kind is None
            else {
                "kind": destination_kind,
                "identity": ("foreign", destination_kind, 73),
                "mode": 0o100640,
                "links": 2 if destination_kind == "hardlink" else 1,
                "bytes": b"other-creator",
                "target": "foreign-target",
            }
        )
        self.foreign_before = copy.deepcopy(self.foreign_destination)
        self.race_at_rename = race_at_rename
        self.race_kind = race_kind or "regular"
        self.committed = False
        self.root_eligible = True
        self.native_calls = []
        self.unlink_calls = []
        self.acl_checks = []
        self.chmod_calls = []
        self.fsyncs = []
        self.directory_fd = 101
        self.temporary_basename = "payload.tmp"
        self.destination_basename = (
            "update-000000.f5w" if kind == "checkpoint" else "protocol.json"
        )

    def validate_payload_semantics(
        self,
        relative_path,
        payload,
        semantic_sha256,
    ):
        self._record(
            "validate_payload_semantics",
            relative_path,
            payload,
            semantic_sha256,
        )
        expected_payload = b'{"schema":"fixture"}\n'
        expected_semantic = hashlib.sha256(
            b"f5-canonical-json-v1\0" + expected_payload
        ).hexdigest()
        if (
            self.kind != "payload"
            or relative_path != "protocol.json"
            or payload != expected_payload
            or semantic_sha256 != expected_semantic
        ):
            raise AssertionError("payload semantics were not authenticated")

    def validate_checkpoint_semantics(
        self,
        update,
        raw_checkpoint,
        tensor_sha256,
    ):
        self._record(
            "validate_checkpoint_semantics",
            update,
            raw_checkpoint,
            tensor_sha256,
        )
        expected_checkpoint = bytes(879900)
        expected_semantic = (
            "3ee7f9703060a491ffbc13194be5a4d74"
            "702bdbe1395ce9cb68d5f87277a28de"
        )
        if (
            self.kind != "checkpoint"
            or update != 0
            or raw_checkpoint != expected_checkpoint
            or tensor_sha256 != expected_semantic
        ):
            raise AssertionError(
                "checkpoint semantics were not authenticated"
            )

    def _record(self, name, *args, **kwargs):
        if name == "require_destination_absent_nofollow":
            self.events.append(name)
            self.calls.append((name, args, kwargs))
            if self.foreign_destination is not None:
                raise FileExistsError(errno.EEXIST, "foreign destination")
            if self.fail_at == name:
                raise _InjectedPublicationFailure(name)
            return None
        if name == "rename_exclusive":
            self.events.append(name)
            self.calls.append((name, args, kwargs))
            if self.race_at_rename:
                self.foreign_destination = {
                    "kind": self.race_kind,
                    "identity": ("foreign", self.race_kind, 79),
                    "mode": 0o100600,
                    "links": 1,
                    "bytes": b"racing-creator",
                    "target": None,
                }
                self.foreign_before = copy.deepcopy(
                    self.foreign_destination
                )
                raise FileExistsError(errno.EEXIST, "racing destination")
            if self.fail_at == name:
                raise _InjectedPublicationFailure(name)
            self.native_calls.append(
                (
                    self.directory_fd,
                    self.temporary_basename.encode("ascii"),
                    self.directory_fd,
                    self.destination_basename.encode("ascii"),
                    0x00000004,
                )
            )
            self.destination_identity = self.source_identity
            self.source_identity = None
            self.committed = True
            return None
        try:
            result = super()._record(name, *args, **kwargs)
        except _InjectedPublicationFailure:
            if self.committed:
                self.root_eligible = False
            raise
        if name.startswith("require_") and name.endswith("_no_acl"):
            self.acl_checks.append(name)
        elif name == "fchmod_temporary_0600":
            self.chmod_calls.append(0o600)
        elif name.startswith("fsync_"):
            self.fsyncs.append(name)
        return result


