class _RealDarwinLeafPublicationIO:
    def __init__(
        self,
        protocol,
        libc,
        directory,
        *,
        destination_basename,
        payload,
    ):
        self.protocol = protocol
        self.libc = libc
        self.directory = pathlib.Path(directory)
        self.destination_basename = destination_basename
        self.temporary_basename = "leaf.tmp"
        self.payload = payload
        self.directory_fd = os.open(
            self.directory,
            os.O_RDONLY | os.O_DIRECTORY,
        )
        self.temporary_fd = None
        self.destination_fd = None
        self.temporary_identity = None
        self.events = []

    def close(self):
        _close_fd(self.destination_fd)
        self.destination_fd = None
        _close_fd(self.temporary_fd)
        self.temporary_fd = None
        _close_fd(self.directory_fd)
        self.directory_fd = None

    def validate_payload_semantics(
        self,
        relative_path,
        payload,
        semantic_sha256,
    ):
        self.events.append("validate_payload_semantics")
        expected_semantic = hashlib.sha256(
            b"f5-canonical-json-v1\0" + self.payload
        ).hexdigest()
        try:
            decoded = json.loads(self.payload)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise AssertionError("payload is not canonical JSON") from error
        if (
            relative_path != self.destination_basename
            or payload != self.payload
            or payload != _canonical_json_fixture(decoded)
            or semantic_sha256 != expected_semantic
        ):
            raise AssertionError("real payload semantic identity mismatch")

    def validate_checkpoint_semantics(
        self,
        update,
        raw_checkpoint,
        tensor_sha256,
    ):
        self.events.append("validate_checkpoint_semantics")
        if (
            update != 0
            or raw_checkpoint != self.payload
            or len(raw_checkpoint) != 879900
            or tensor_sha256
            != _canonical_tensor_sha256_from_raw_fixture(raw_checkpoint)
        ):
            raise AssertionError(
                "real checkpoint semantic identity mismatch"
            )

    def create_temporary_new(self, *args, **kwargs):
        self.events.append("create_temporary_new")
        self.temporary_fd = os.open(
            self.temporary_basename,
            (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_NOFOLLOW", 0)
            ),
            0o600,
            dir_fd=self.directory_fd,
        )
        self.temporary_identity = os.fstat(self.temporary_fd)

    def fchmod_temporary_0600(self, *args, **kwargs):
        self.events.append("fchmod_temporary_0600")
        os.fchmod(self.temporary_fd, 0o600)

    def require_temporary_no_acl(self, *args, **kwargs):
        self.events.append("require_temporary_no_acl")
        self.protocol.require_no_extended_acl(
            self.libc,
            self.temporary_fd,
        )

    def write_all(self, *args, **kwargs):
        self.events.append("write_all")
        remaining = memoryview(self.payload)
        while remaining:
            written = os.write(self.temporary_fd, remaining)
            if written <= 0:
                raise AssertionError("real fixture write made no progress")
            remaining = remaining[written:]

    def flush_temporary(self, *args, **kwargs):
        self.events.append("flush_temporary")

    def fsync_temporary_file(self, *args, **kwargs):
        self.events.append("fsync_temporary_file")
        os.fsync(self.temporary_fd)

    def _require_parent_identity(self):
        path_stat = self.directory.stat()
        descriptor_stat = os.fstat(self.directory_fd)
        if (
            path_stat.st_dev,
            path_stat.st_ino,
            path_stat.st_mode,
        ) != (
            descriptor_stat.st_dev,
            descriptor_stat.st_ino,
            descriptor_stat.st_mode,
        ):
            raise AssertionError("directory path/descriptor identity changed")

    def validate_parent_path_before(self, *args, **kwargs):
        self.events.append("validate_parent_path_before")
        self._require_parent_identity()

    def require_destination_absent_nofollow(self, *args, **kwargs):
        self.events.append("require_destination_absent_nofollow")
        try:
            os.stat(
                self.destination_basename,
                dir_fd=self.directory_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return
        raise FileExistsError(errno.EEXIST, "destination exists")

    def validate_source_name_identity(self, *args, **kwargs):
        self.events.append("validate_source_name_identity")
        named = os.stat(
            self.temporary_basename,
            dir_fd=self.directory_fd,
            follow_symlinks=False,
        )
        held = os.fstat(self.temporary_fd)
        if (
            named.st_dev,
            named.st_ino,
            named.st_mode,
            named.st_nlink,
            named.st_size,
        ) != (
            held.st_dev,
            held.st_ino,
            held.st_mode,
            held.st_nlink,
            held.st_size,
        ):
            raise AssertionError("temporary source identity changed")

    def rename_exclusive(self, *args, **kwargs):
        self.events.append("rename_exclusive")
        self.protocol.exclusive_rename_new(
            self.libc,
            self.directory_fd,
            self.temporary_basename,
            self.directory_fd,
            self.destination_basename,
        )

    def validate_parent_path_after(self, *args, **kwargs):
        self.events.append("validate_parent_path_after")
        self._require_parent_identity()

    def reopen_destination_nofollow(self, *args, **kwargs):
        self.events.append("reopen_destination_nofollow")
        self.destination_fd = os.open(
            self.destination_basename,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=self.directory_fd,
        )
        return self.destination_fd

    def validate_destination_identity(self, *args, **kwargs):
        self.events.append("validate_destination_identity")
        destination = os.fstat(self.destination_fd)
        source = self.temporary_identity
        if (
            destination.st_dev,
            destination.st_ino,
            destination.st_mode & 0o777,
            destination.st_nlink,
            destination.st_size,
        ) != (
            source.st_dev,
            source.st_ino,
            0o600,
            1,
            len(self.payload),
        ):
            raise AssertionError("published leaf identity mismatch")
        observed = b""
        while len(observed) < len(self.payload):
            chunk = os.read(
                self.destination_fd,
                len(self.payload) - len(observed),
            )
            if not chunk:
                break
            observed += chunk
        if observed != self.payload:
            raise AssertionError("published leaf bytes mismatch")

    def require_destination_no_acl(self, *args, **kwargs):
        self.events.append("require_destination_no_acl")
        self.protocol.require_no_extended_acl(
            self.libc,
            self.destination_fd,
        )

    def fsync_containing_directory(self, *args, **kwargs):
        self.events.append("fsync_containing_directory")
        os.fsync(self.directory_fd)


def _prepared_puffer_smoke_unavailability(
    puffer_root: pathlib.Path,
) -> str | None:
    if sys.platform != "darwin":
        return "frozen prepared-Puffer smoke requires Darwin"
    if platform.machine() != "arm64":
        return "frozen prepared-Puffer smoke requires arm64"
    if platform.mac_ver()[0] != "15.6":
        return "frozen prepared-Puffer smoke requires macOS 15.6"
    if os.uname().release != "24.6.0":
        return "frozen prepared-Puffer smoke requires Darwin 24.6.0"
    model = subprocess.run(
        ["/usr/sbin/sysctl", "-n", "hw.model"],
        check=False,
        capture_output=True,
        text=True,
    )
    if model.returncode != 0 or model.stdout.strip() != "Mac16,7":
        return "frozen prepared-Puffer smoke requires Mac16,7"

    root = puffer_root.resolve()
    if not root.is_dir():
        return "prepared Puffer root is absent"
    head = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "HEAD"],
        check=False,
        capture_output=True,
        text=True,
    )
    if (
        head.returncode != 0
        or head.stdout.strip()
        != "9836f0d2e78889c1aaf189c04d161b6fc61a9386"
    ):
        return "prepared Puffer root does not have the frozen base commit"
    status = subprocess.run(
        [
            "/usr/bin/env",
            "-i",
            "PATH=/usr/bin:/bin",
            "LANG=C",
            "LC_ALL=C",
            "git",
            "-C",
            str(root),
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
        ],
        check=False,
        capture_output=True,
    )
    if status.returncode != 0 or status.stderr:
        return "prepared Puffer status command is unavailable"
    if len(status.stdout) != 3437:
        return "prepared Puffer status byte count is not frozen"
    if hashlib.sha256(
        b"bloodbowl-f5-git-status-v1\0" + status.stdout
    ).hexdigest() != (
        "60ff30fe6d00bd26ff2e7b2c041b44db2f1cade0dc3577c13e070dc7a7de57f2"
    ):
        return "prepared Puffer status digest is not frozen"

    module = root / "pufferlib/_C.cpython-312-darwin.so"
    if not module.is_file() or module.is_symlink():
        return "qualified F5 compiled module is absent"
    if hashlib.sha256(module.read_bytes()).hexdigest() != (
        "0dd03bcf444f84241ef8f6724b5e7d1e8c572c56d66714ccd44c1f5be69f1488"
    ):
        return "qualified F5 compiled module digest is not frozen"

    interpreter = root / ".venv/bin/python3.12"
    if not interpreter.exists():
        return "prepared CPython 3.12 interpreter is absent"
    if hashlib.sha256(interpreter.resolve().read_bytes()).hexdigest() != (
        "d4706f4e64be2b6f94083b270a529469955f56d2438c03182427209fbbb65752"
    ):
        return "prepared CPython executable digest is not frozen"
    source_hashes = {
        "pufferlib/pufferl.py": (
            "22bbbe209f5d73a397863b15ecb5e76af0617143bf8bf7158381f560f957526c"
        ),
        "pufferlib/torch_pufferl.py": (
            "30e36f98951b7c38541156835f83c06e6a8b3b475b65349812313825da36daec"
        ),
        "pufferlib/models.py": (
            "def01bf10ce48eabe9743a9dfb4d5ad635c214e14b07219e5c929b6ae61afd59"
        ),
        "pufferlib/muon.py": (
            "105bfc542cdb125e384a3290f7d282b212379836bc9983290948b12b860ba888"
        ),
        "config/default.ini": (
            "6b129902269d99e5434a47a175e3ac4c13f30af4e4da613ebe158b02cd5bd9cc"
        ),
        "config/bloodbowl.ini": (
            "7ef064026b2d098d42d12c7ca67e1dd5b8ae3c4d584f788c03916a7d6bd08f1e"
        ),
    }
    for relative, expected_sha256 in source_hashes.items():
        path = root / relative
        if (
            not path.is_file()
            or path.is_symlink()
            or hashlib.sha256(path.read_bytes()).hexdigest()
            != expected_sha256
        ):
            return f"prepared Puffer source drifted: {relative}"
    probe = subprocess.run(
        [
            str(interpreter),
            "-B",
            "-s",
            "-P",
            "-c",
            (
                "import json,sys,torch;"
                "print(json.dumps({"
                "'python':sys.version.split()[0],"
                "'torch':torch.__version__,"
                "'torch_git':torch.version.git_version"
                "},sort_keys=True,separators=(',',':')))"
            ),
        ],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    if probe.returncode != 0 or probe.stderr:
        return "prepared Python/Torch runtime probe failed"
    try:
        runtime = json.loads(probe.stdout)
    except json.JSONDecodeError:
        return "prepared Python/Torch runtime probe was not JSON"
    if runtime != {
        "python": "3.12.12",
        "torch": "2.9.1",
        "torch_git": "5811a8d7da873dd699ff6687092c225caffcf1bb",
    }:
        return "prepared Python/Torch runtime identity is not frozen"
    return None


def _exact_final_consumer_unavailability() -> str | None:
    if sys.platform != "darwin":
        return "exact final consumer requires the frozen Darwin host"
    if platform.machine() != "arm64":
        return "exact final consumer requires arm64"
    if platform.mac_ver()[0] != "15.6":
        return "exact final consumer requires macOS 15.6"
    if os.uname().release != "24.6.0":
        return "exact final consumer requires Darwin 24.6.0"
    model = subprocess.run(
        ["/usr/sbin/sysctl", "-n", "hw.model"],
        check=False,
        capture_output=True,
    )
    if (
        model.returncode != 0
        or model.stderr
        or model.stdout.strip() != b"Mac16,7"
    ):
        return "exact final consumer requires Mac16,7"
    identities = (
        (
            pathlib.Path("/usr/bin/env"),
            (
                "7259ae24c7f1907eede9230ddc3c6b44e"
                "811c64f9ccc0073681d560094e092f0"
            ),
        ),
        (
            pathlib.Path("/usr/bin/python3"),
            (
                "7588ceab299393618d6f8861502ac0588"
                "d1594025f301d9a61a898215b5571d3"
            ),
        ),
    )
    for path, expected in identities:
        if not path.is_file() or hashlib.sha256(
            path.read_bytes()
        ).hexdigest() != expected:
            return "exact final-consumer executable identity is absent"
    probe = subprocess.run(
        [
            "/usr/bin/python3",
            "-B",
            "-I",
            "-S",
            "-c",
            (
                "import json,sys;"
                "print(json.dumps({"
                "'version':sys.version.split()[0],"
                "'isolated':sys.flags.isolated,"
                "'ignore_environment':sys.flags.ignore_environment,"
                "'no_site':sys.flags.no_site,"
                "'executable':sys.executable,"
                "'path':sys.path},sort_keys=True))"
            ),
        ],
        check=False,
        capture_output=True,
    )
    if probe.returncode != 0 or probe.stderr:
        return "exact final-consumer CPython probe failed"
    try:
        observed = json.loads(probe.stdout)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return "exact final-consumer CPython probe was malformed"
    if (
        observed["version"] != "3.9.6"
        or observed["isolated"] != 1
        or observed["ignore_environment"] != 1
        or observed["no_site"] != 1
        or len(observed["path"]) != 3
    ):
        return "exact final-consumer CPython flags are absent"
    resolved_executable = pathlib.Path(observed["executable"])
    if (
        not resolved_executable.is_file()
        or hashlib.sha256(
            resolved_executable.read_bytes()
        ).hexdigest()
        != (
            "e7276a0ac27acdd53135450bd3038e8a6"
            "d77aad9df9ee06b05ef311ce9955db9"
        )
    ):
        return "exact resolved Xcode CPython identity is absent"
    return None


def _run_exact_final_consumer_fixture(
    source_root: pathlib.Path,
    artifact_root: pathlib.Path,
    expected_verdict_sha256: str,
) -> subprocess.CompletedProcess:
    return subprocess.run(
        [
            "/usr/bin/env",
            "-i",
            "PATH=/usr/bin:/bin",
            "LANG=C",
            "LC_ALL=C",
            "TMPDIR=/private/tmp",
            "/usr/bin/python3",
            "-B",
            "-I",
            "-S",
            str(
                source_root
                / "tools/verify_f5_recurrent_ppo_pilot.py"
            ),
            "--consume-final",
            "--artifact-dir",
            str(artifact_root.resolve()),
            "--expected-verdict-sha256",
            expected_verdict_sha256,
        ],
        check=False,
        capture_output=True,
        timeout=60,
    )


def _validate_prepared_one_update_smoke_receipt(
    receipt: dict,
    *,
    manifest: dict,
    puffer_root: pathlib.Path,
) -> None:
    expected_keys = {
        "arguments",
        "call_order",
        "create_vec",
        "digests",
        "initial_raw_checkpoint",
        "model",
        "module_sha256",
        "puffer_commit",
        "puffer_root",
        "puffer_source_manifest_sha256",
        "pufferl",
        "post_update_raw_checkpoint",
        "runtime",
        "schema",
        "seeding",
        "update",
    }
    if set(receipt) != expected_keys:
        raise AssertionError("prepared smoke receipt root is not closed")
    arguments = manifest["puffer"]["arguments"]
    if receipt["schema"] != "bloodbowl-f5-one-update-smoke-v1":
        raise AssertionError("prepared smoke schema drifted")
    if pathlib.Path(receipt["puffer_root"]).resolve() != puffer_root.resolve():
        raise AssertionError("prepared smoke did not consume requested root")
    if (
        receipt["puffer_commit"]
        != "9836f0d2e78889c1aaf189c04d161b6fc61a9386"
    ):
        raise AssertionError("prepared smoke Puffer commit drifted")
    if receipt["module_sha256"] != (
        "0dd03bcf444f84241ef8f6724b5e7d1e8c572c56d66714ccd44c1f5be69f1488"
    ):
        raise AssertionError("prepared smoke module digest drifted")
    if receipt["puffer_source_manifest_sha256"] != (
        "961915f4caf5e0767ce8caaf6ae6e2623bfa3591befcb2913ba5eac561d82f2b"
    ):
        raise AssertionError("prepared smoke Puffer source manifest drifted")
    if receipt["arguments"] != arguments:
        raise AssertionError("prepared smoke effective arguments drifted")
    if receipt["create_vec"] != {
        "arguments": {
            "env": arguments["env"],
            "vec": arguments["vec"],
        },
        "gpu": 0,
    }:
        raise AssertionError("prepared smoke create_vec wiring drifted")
    model = receipt["model"]
    if set(model) != {
        "action_head_count",
        "action_logit_count",
        "construction_order",
        "decoder_act_sizes",
        "encoder_obs_size",
        "hidden_size",
        "network_kwargs",
        "trainable_parameters",
    }:
        raise AssertionError("prepared smoke model receipt is not closed")
    if model["construction_order"] != [
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
    ]:
        raise AssertionError("prepared smoke construction order drifted")
    if model["network_kwargs"] != {
        "expansion_factor": 1,
        "hidden_size": 64,
        "num_layers": 1,
    }:
        raise AssertionError("prepared smoke MinGRU arguments drifted")
    if model["encoder_obs_size"] != 2782:
        raise AssertionError("prepared smoke encoder obs size drifted")
    if model["hidden_size"] != 64:
        raise AssertionError("prepared smoke hidden size drifted")
    if model["action_head_count"] != 3:
        raise AssertionError("prepared smoke action-head count drifted")
    if (
        type(model["decoder_act_sizes"]) is not list
        or len(model["decoder_act_sizes"]) != 3
        or any(
            type(value) is not int or value <= 0
            for value in model["decoder_act_sizes"]
        )
        or sum(model["decoder_act_sizes"]) != 454
        or model["action_logit_count"] != 454
    ):
        raise AssertionError("prepared smoke decoder action sizes drifted")
    if model["trainable_parameters"] != 219975:
        raise AssertionError("prepared smoke parameter count drifted")
    if receipt["pufferl"] != {
        "arguments_sha256": EXPECTED_EFFECTIVE_ARGUMENTS_SHA256,
        "verbose": False,
    }:
        raise AssertionError("prepared smoke PuffeRL wiring drifted")
    if receipt["seeding"] != {
        "evaluation_construction": 38865036,
        "model_initialization": 1937413891,
        "numpy_process": 3265398457,
        "python_process": 249709497,
        "training_torch": 2415287173,
    }:
        raise AssertionError("prepared smoke seed values drifted")
    if receipt["runtime"] != {
        "cuda_selected": False,
        "deterministic_algorithms": True,
        "device": "cpu",
        "interop_threads": 1,
        "intraop_threads": 4,
        "omp_dynamic": "FALSE",
        "omp_num_threads": "4",
        "python_version": "3.12.12",
        "torch_git_revision": (
            "5811a8d7da873dd699ff6687092c225caffcf1bb"
        ),
        "torch_version": "2.9.1",
        "vec_num_threads": 20,
        "worker_environment": EXPECTED_WORKER_ENVIRONMENT,
        "worker_environment_sha256": (
            "de1e11609f4c0bec54a69894149f0200a3a41d94352fac3eb529b1290a0015da"
        ),
    }:
        raise AssertionError("prepared smoke runtime wiring drifted")
    if receipt["update"] != {
        "accepted_global_agent_step": 32768,
        "committed_epoch": 1,
        "full_schedule_updates": 2956,
        "gate_before_train": True,
        "minibatches": 1,
        "rollouts_returned_none": True,
        "stopped_after_updates": 1,
        "tail_valid_after_train": False,
    }:
        raise AssertionError("prepared smoke update receipt drifted")
    if receipt["digests"] != {
        "duplicate_initial_canonical_sha256": (
            EXPECTED_INITIAL_PARAMETER_SHA256
        ),
        "initial_canonical_sha256": EXPECTED_INITIAL_PARAMETER_SHA256,
        "initial_raw_sha256": EXPECTED_INITIAL_RAW_SHA256,
        "post_update_canonical_sha256": (
            EXPECTED_ONE_UPDATE_PARAMETER_SHA256
        ),
        "post_update_raw_sha256": EXPECTED_ONE_UPDATE_RAW_SHA256,
    }:
        raise AssertionError("prepared smoke tensor digests drifted")
    initial_raw = receipt["initial_raw_checkpoint"]
    post_update_raw = receipt["post_update_raw_checkpoint"]
    if (
        type(initial_raw) is not bytes
        or len(initial_raw) != 879900
        or hashlib.sha256(initial_raw).hexdigest()
        != EXPECTED_INITIAL_RAW_SHA256
        or _canonical_tensor_sha256_from_raw_fixture(initial_raw)
        != EXPECTED_INITIAL_PARAMETER_SHA256
    ):
        raise AssertionError(
            "prepared smoke did not return the exact initial raw tensors"
        )
    if (
        type(post_update_raw) is not bytes
        or len(post_update_raw) != 879900
        or hashlib.sha256(post_update_raw).hexdigest()
        != EXPECTED_ONE_UPDATE_RAW_SHA256
        or _canonical_tensor_sha256_from_raw_fixture(post_update_raw)
        != EXPECTED_ONE_UPDATE_PARAMETER_SHA256
    ):
        raise AssertionError(
            "prepared smoke did not return the exact post-update raw tensors"
        )
    if receipt["call_order"] != [
        "random.seed:249709497",
        "numpy.random.seed:3265398457",
        "torch.manual_seed:1937413891",
        "torch.use_deterministic_algorithms:true",
        "torch.set_num_threads:4",
        "torch.set_num_interop_threads:1",
        "_C.create_vec:gpu=0",
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
        "torch.manual_seed:1937413891",
        "MinGRU",
        "DefaultEncoder",
        "DefaultDecoder",
        "Policy",
        "PuffeRL:verbose=false",
        "torch.manual_seed:2415287173",
        "rollouts",
        "validate_live_rollout",
        "train",
    ]:
        raise AssertionError("prepared smoke direct call order drifted")


def _run_prepared_puffer_duplicate_one_update_smoke(
    puffer_root: pathlib.Path,
) -> list[dict]:
    reason = _prepared_puffer_smoke_unavailability(puffer_root)
    if reason is not None:
        raise AssertionError(reason)
    runner = _runner()
    signature = inspect.signature(
        runner.run_prepared_one_update_smoke
    )
    if tuple(signature.parameters) != ("puffer_root",):
        raise AssertionError(
            "prepared smoke entry point must accept only puffer_root"
        )
    manifest = _protocol().load_protocol_manifest()
    receipts = []
    for _ in range(2):
        receipt = runner.run_prepared_one_update_smoke(
            str(puffer_root.resolve())
        )
        _validate_prepared_one_update_smoke_receipt(
            receipt,
            manifest=manifest,
            puffer_root=puffer_root,
        )
        receipts.append(receipt)
    if receipts[0] != receipts[1]:
        raise AssertionError(
            "duplicate prepared one-update smoke receipts differ"
        )
    return receipts


def _test_stream_contract_fixture(
    *,
    nonce="17" * 16,
    population="controller",
    repeat_flag=0,
):
    """Build a small Python-3.9-safe evaluation framing transcript."""
    job = {
        "action_seed": EVALUATION_ACTION_SEEDS[0],
        "artifact_root": "/private/tmp/f5-stream-artifact",
        "checkpoint_raw_sha256": "1" * 64,
        "checkpoint_tensor_sha256": "2" * 64,
        "checkpoint_update": 0,
        "implementation_manifest_sha256": "3" * 64,
        "nonce": nonce,
        "population": population,
        "protocol_sha256": EXPECTED_PROTOCOL_MANIFEST_SHA256,
        "puffer_root": "/private/tmp/f5-stream-puffer",
        "repeat_flag": repeat_flag,
        "schema": "bloodbowl-f5-evaluation-worker-job-v1",
        "seed_index": 0,
        "source_commit": "4" * 40,
        "source_root": "/private/tmp/f5-stream-source",
        "supervisor_pid": 4242,
        "whole_deadline_monotonic_ns": 9_000_000_000_000,
        "worker_kind": "evaluation",
    }
    job_wire = _test_worker_job_bytes(job)
    job_sha256 = hashlib.sha256(
        b"bloodbowl-f5-worker-job-v1\0" + job_wire[4:]
    ).hexdigest()
    payloads = (
        b"\x01" + b"\x00" * 4095,
        (b'{"synthetic":true}\n' * 3685)[:70_000],
    )
    sequence = _test_stream_evaluation_topology(job)
    frames = []
    for index, payload in enumerate(payloads):
        expected = sequence[index]
        domain = expected["semantic_domain"].encode("ascii") + b"\0"
        frames.append(
            _test_build_self_consistent_worker_frame(
                payload=payload,
                frame_index=index,
                kind=expected["kind"],
                logical_name=expected["logical_name"],
                job_sha256=job_sha256,
                nonce=nonce,
                semantic_sha256=hashlib.sha256(
                    domain + payload
                ).hexdigest(),
            )
        )
    return {
        "expected_sequence": sequence,
        "frames": tuple(frames),
        "job": job,
        "job_wire": job_wire,
        "payloads": payloads,
        "stdout": b"".join(frame["wire"] for frame in frames),
    }


