    def test_manifest_owns_supervision_and_public_failure_state_matrices(
        self,
    ) -> None:
        supervision = self.manifest["execution"]["supervision"]
        self.assertEqual(
            supervision["child_waits"],
            {
                "blocking_communicate_allowed": False,
                "blocking_pipe_io_allowed": False,
                "blocking_wait_allowed": False,
                "poll_slice_nanoseconds": (
                    SIGNAL_RESPONSE_POLL_NANOSECONDS
                ),
                "signal_then_deadline_before_and_after_wait": True,
            },
        )
        self.assertEqual(
            supervision["first_origin_precedence"],
            {
                "descriptor_service_order": ["stderr", "stdout"],
                "immutable_after_selection": True,
                "normal_exit_deferred_until_stream_table": True,
                "readiness_turn_order": [
                    "signal-latch",
                    "monotonic-deadline",
                    "nonblocking-child-status",
                    "stderr",
                    "stdout",
                ],
            },
        )
        self.assertEqual(
            tuple(supervision["resource_errnos"]),
            RESOURCE_ERRNO_NAMES,
        )
        self.assertEqual(supervision["population"]["retries"], 0)
        self.assertEqual(
            supervision["population"]["maximum_live_prepared_workers"],
            1,
        )
        self.assertFalse(
            supervision["population"]["next_worker_after_failure_allowed"]
        )
        self.assertEqual(
            supervision["termination"]["order"],
            [
                "close-input",
                "SIGTERM",
                "concurrent-drain-and-nonblocking-reap",
                "SIGKILL-if-still-live-at-grace",
                "unconditional-reap",
            ],
        )
        self.assertEqual(
            supervision["termination"]["grace_seconds"],
            TERMINATION_GRACE_SECONDS,
        )
        self.assertTrue(supervision["termination"]["preserve_origin"])
        self.assertEqual(
            supervision["stream_exit_table"],
            [
                {
                    "exit": "unrequested-signal",
                    "frames": "any-prefix",
                    "mapping": "worker-signal",
                },
                {
                    "exit": "any-normal",
                    "frames": "zero",
                    "mapping": "ipc-contract",
                },
                {
                    "exit": "any-normal",
                    "frames": "partial-or-nonfinal-proper-prefix",
                    "mapping": "ipc-contract",
                },
                {
                    "exit": 0,
                    "frames": "complete-success-sequence",
                    "mapping": "candidate-success",
                },
                {
                    "exit": "normal-nonzero",
                    "frames": "complete-success-sequence",
                    "mapping": "worker-exit",
                },
                {
                    "exit": "matching-70-or-75",
                    "frames": "one-complete-failure-frame",
                    "mapping": "mapped-typed-failure",
                },
                {
                    "exit": "other-normal",
                    "frames": "one-complete-failure-frame",
                    "mapping": "worker-exit",
                },
            ],
        )

        receipts = self.manifest["execution"]["failure_receipts"]
        self.assertEqual(
            tuple(receipts["controller"]["schema"]["fields"]),
            CONTROLLER_FAILURE_RECEIPT_FIELDS,
        )
        self.assertEqual(
            tuple(receipts["verifier"]["schema"]["fields"]),
            VERIFIER_FAILURE_RECEIPT_FIELDS,
        )
        self.assertEqual(
            {
                phase: tuple(causes)
                for phase, causes in receipts["controller"][
                    "phase_causes"
                ].items()
            },
            CONTROLLER_PHASE_CAUSES,
        )
        self.assertEqual(
            {
                phase: tuple(causes)
                for phase, causes in receipts["verifier"][
                    "phase_causes"
                ].items()
            },
            VERIFIER_PHASE_CAUSES,
        )
        self.assertEqual(
            receipts["controller"]["topology"][
                "container_immediate_paths_after_receipt"
            ],
            ["artifact", "receipt.json"],
        )
        self.assertEqual(
            receipts["controller"]["topology"][
                "container_link_count_apfs"
            ],
            4,
        )
        self.assertFalse(
            receipts["controller"]["topology"][
                "receipt_inside_artifact_child"
            ]
        )
        self.assertFalse(
            receipts["controller"]["topology"][
                "runtime_scratch_inside_container"
            ]
        )
        self.assertEqual(
            receipts["verifier"]["topology"][
                "directory_immediate_paths_after_receipt"
            ],
            ["receipt.json"],
        )
        self.assertEqual(
            receipts["verifier"]["topology"]["directory_link_count_apfs"],
            3,
        )
        nonce = receipts["nonce_generation"]
        self.assertEqual(nonce["call"], "os.urandom(16).hex()")
        self.assertEqual(nonce["calls_per_object"], 1)
        self.assertFalse(nonce["collision_retry"])
        self.assertFalse(nonce["invalid_result_retry"])
        self.assertFalse(nonce["in_memory_reuse_allowed"])
        self.assertEqual(
            nonce["objects"],
            [
                "worker-job",
                "controller-incomplete-container",
                "verifier-incomplete-directory",
                "controller-publication-intent-directory",
                "verifier-publication-intent-directory",
            ],
        )
        output = receipts["public_output"]
        self.assertEqual(
            output["temporary_nonblocking_transaction"][
                "descriptor_operations"
            ],
            [
                "F_GETFL",
                "F_SETFL(saved|O_NONBLOCK)",
                "verify",
                "bounded-offset-write",
                "unconditional-F_SETFL(saved)",
                "verify-exact-restoration",
            ],
        )
        self.assertEqual(
            output["precommit_failure"]["poll_nanoseconds"],
            SIGNAL_RESPONSE_POLL_NANOSECONDS,
        )
        self.assertEqual(
            output["postcommit_result"]["poll_nanoseconds"],
            SIGNAL_RESPONSE_POLL_NANOSECONDS,
        )
        self.assertEqual(
            output["postcommit_result"]["exit_on_channel_failure"],
            0,
        )
        self.assertFalse(
            output["postcommit_result"]["failure_receipt_allowed"]
        )

    def test_manifest_owns_commit_inspection_transaction_muon_and_telemetry(
        self,
    ) -> None:
        execution = self.manifest["execution"]
        publication = execution["publication"]["child_supervision"]
        self.assertEqual(
            publication,
            execution["supervision"]["publication_child"],
        )
        self.assertTrue(
            publication["every_nonclean_event_commit_aware"]
        )
        self.assertEqual(
            publication["readiness_order"],
            [
                "first-signal-latch",
                "monotonic-deadline",
                "nonblocking-child-status",
                "stderr",
                "stdout",
                "handoff-record-pipe",
                "ACK-write-endpoint",
            ],
        )
        outcomes = publication["commit_inspection_outcomes"]
        for key in (
            "exact_commit_with_durable_handoff",
            "possible_commit_with_durable_handoff",
        ):
            self.assertEqual(
                outcomes[key],
                {
                    "failure_receipt_allowed": False,
                    "public_exit": 0,
                    "public_result": "publication-indeterminate",
                    "rollback_allowed": False,
                },
            )
        self.assertEqual(
            outcomes[
                "possible_or_exact_commit_without_durable_handoff"
            ],
            {
                "failure_receipt_allowed": False,
                "public_exit": 70,
                "public_result": None,
                "rollback_allowed": False,
                "stderr": "normal-integrity-failure-line",
            },
        )
        self.assertEqual(
            publication["normal_exit_after_descriptor_drain"],
            {
                "0": "candidate-clean-completion",
                "70": "publication-precommit",
                "75": "filesystem-resource",
            },
        )
        self.assertEqual(
            publication["handoff_zero_byte_eof"],
            {
                "normal_exit_0": "publication-precommit",
                "normal_exit_70": "publication-precommit",
                "normal_exit_75": "filesystem-resource",
            },
        )
        self.assertEqual(
            publication["termination"]["order"][-1],
            "source-destination-descriptor-inspection",
        )

        umask = execution["security"]["umask"]
        self.assertEqual(umask["operation"], "posix.umask")
        self.assertEqual(umask["module"], "sys.modules[posix]")
        self.assertEqual(umask["module_origin"], "built-in")
        self.assertEqual(umask["value"], 63)
        self.assertEqual(umask["call_count_per_selected_process"], 1)
        self.assertTrue(umask["first_process_state_protocol_operation"])
        self.assertFalse(umask["previous_value_restored"])
        self.assertFalse(umask["previous_value_evidence_allowed"])

        transaction = execution["rollout"]["transaction"]
        self.assertEqual(
            transaction["accepted_commit_order"],
            [
                "complete-rollout",
                "rollout-alignment-and-flat-log-validation",
                "optimizer-update-completes",
                "complete-trace-row-schema-and-semantic-validation",
                "append-accepted-trace-row",
                "advance-accepted-global-agent-step",
                "optional-fixed-schedule-checkpoint",
            ],
        )
        self.assertTrue(
            transaction["integrity_failure"][
                "discard_before_receipt_attempt"
            ]
        )
        self.assertTrue(
            transaction["integrity_failure"][
                "same_session_operation_rejected_before_rollout"
            ]
        )
        self.assertFalse(
            transaction["integrity_failure"][
                "receipt_failure_undoes_discard"
            ]
        )
        smoke = execution["smoke"]
        self.assertEqual(
            smoke["one_update_raw_sha256"],
            EXPECTED_ONE_UPDATE_RAW_SHA256,
        )
        early = smoke["early_terminal_abort"]
        self.assertEqual(
            early["cases"],
            {
                "agent_rows": [0, 1],
                "all_cases_same_prepared_python_process": True,
                "delayed_rows": [1, 2, 3, 4, 5, 6, 7],
                "fresh_sessions": 7,
                "injected_terminal_pairs_per_case": 1,
                "injection_path": (
                    "test-owned-wrapper-around-real-compiled-cpu_step"
                ),
                "one_live_learner_at_a_time": True,
                "prepared_python_process_count": 1,
                "serial": True,
            },
        )
