    def test_masked_uniform_comparator_uses_stable_log1p_expm1_formula(
        self,
    ) -> None:
        comparator = self.manifest["budget"]["masked_uniform"]
        numerator = comparator["numerator"]
        denominator = comparator["denominator"]
        episodes = self.manifest["budget"]["episodes"]
        probability = numerator / denominator
        minimum = math.ceil(math.log(0.05) / math.log1p(-probability))
        at_budget = -math.expm1(episodes * math.log1p(-probability))
        self.assertEqual(minimum, 6052775)
        self.assertEqual(comparator["minimum_episodes_95"], minimum)
        self.assertEqual(round(at_budget, 10), 0.9500275582)
        self.assertEqual(
            comparator["probability_at_budget_rounded_10"],
            0.9500275582,
        )
        self.assertEqual(
            self.protocol.masked_uniform_comparator(
                numerator,
                denominator,
                episodes,
            ),
            {
                "minimum_episodes_95": 6052775,
                "probability_at_budget_rounded_10": 0.9500275582,
            },
        )

