    def test_schema_validator_rejects_boolean_as_integer_and_extra_keys(
        self,
    ) -> None:
        empty_registry = {
            "definitions": {},
            "roots": {},
            "schema": "bloodbowl-f5-schema-registry-v1",
        }
        integer = {"kind": "integer", "minimum": 0, "maximum": 4}
        self.protocol.validate_schema(3, integer, empty_registry)
        for invalid in (True, -1, 5, 1.0):
            with self.subTest(invalid=invalid):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_schema(
                        invalid, integer, empty_registry
                    )
        closed = {
            "closed": True,
            "fields": {"x": integer},
            "kind": "object",
        }
        self.protocol.validate_schema({"x": 1}, closed, empty_registry)
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.validate_schema(
                {"x": 1, "extension": 2},
                closed,
                empty_registry,
            )

    def test_schema_validator_keeps_integer_number_and_zero_sign_disjoint(
        self,
    ) -> None:
        registry = {
            "definitions": {},
            "roots": {},
            "schema": "bloodbowl-f5-schema-registry-v1",
        }
        number = {
            "finite": True,
            "kind": "number",
            "maximum": 1.0,
            "minimum": 0.0,
        }
        self.protocol.validate_schema(0.0, number, registry)
        self.protocol.validate_schema(0.5, number, registry)
        self.protocol.validate_schema(1.0, number, registry)
        for invalid in (
            False,
            True,
            0,
            1,
            -0.0,
            -1e-300,
            1.0000000000000002,
            math.nan,
            math.inf,
            -math.inf,
        ):
            with self.subTest(kind="number", invalid=invalid):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.validate_schema(
                        invalid,
                        number,
                        registry,
                    )

        literal = {"kind": "literal", "value": 0.0}
        enum = {"kind": "enum", "values": [0.0, 1.0]}
        nullable = {
            "kind": "union",
            "options": [
                {"kind": "null"},
                copy.deepcopy(number),
            ],
        }
        self.protocol.validate_schema(0.0, literal, registry)
        self.protocol.validate_schema(0.0, enum, registry)
        self.protocol.validate_schema(None, nullable, registry)
        self.protocol.validate_schema(0.0, nullable, registry)
        for node_name, node in (
            ("literal", literal),
            ("enum", enum),
            ("nullable-number", nullable),
        ):
            for invalid in (-0.0, 0, False):
                with self.subTest(node=node_name, invalid=invalid):
                    with self.assertRaises(self.protocol.ProtocolError):
                        self.protocol.validate_schema(
                            invalid,
                            node,
                            registry,
                        )

        adjacent = math.nextafter(0.0, 1.0)
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.validate_schema(
                adjacent,
                literal,
                registry,
            )

