@requires_implementation
class F5RecurrentPpoRolloutAlignmentContract(unittest.TestCase):
    def setUp(self) -> None:
        self.protocol = _protocol()

    def test_rollout_log_manifest_owns_exact_raw_projection_authority(
        self,
    ) -> None:
        manifest = self.protocol.load_protocol_manifest()
        authority = manifest["execution"]["rollout_log"]
        self.assertEqual(
            set(authority),
            {
                "derived",
                "native_keys",
                "native_keys_sha256",
                "projections",
                "validated_unretained",
            },
        )
        self.assertEqual(tuple(authority["native_keys"]), PUFFER_RAW_LOG_KEYS)
        self.assertEqual(len(PUFFER_RAW_LOG_KEYS), 153)
        self.assertEqual(len(set(PUFFER_RAW_LOG_KEYS)), 153)
        self.assertEqual(
            hashlib.sha256(
                _canonical_json_fixture(list(PUFFER_RAW_LOG_KEYS))
            ).hexdigest(),
            PUFFER_RAW_LOG_KEYS_SHA256,
        )
        self.assertEqual(
            authority["native_keys_sha256"],
            PUFFER_RAW_LOG_KEYS_SHA256,
        )
        expected_projections = [
            {
                "native": native,
                "operation": operation,
                "target": target,
            }
            for native, operation, target in ROLLOUT_LOG_PROJECTIONS
        ]
        self.assertEqual(authority["projections"], expected_projections)
        self.assertEqual(len(expected_projections), 83)
        self.assertEqual(
            tuple(record["native"] for record in expected_projections),
            tuple(
                sorted(record["native"] for record in expected_projections)
            ),
        )
        self.assertEqual(
            {
                record["operation"] for record in expected_projections
            },
            set(ROLLOUT_LOG_OPERATIONS),
        )
        self.assertTrue(
            all(set(record) == {"native", "operation", "target"}
                for record in expected_projections)
        )
        self.assertEqual(
            tuple(authority["validated_unretained"]),
            ROLLOUT_LOG_VALIDATED_UNRETAINED,
        )
        self.assertEqual(len(ROLLOUT_LOG_VALIDATED_UNRETAINED), 70)
        self.assertEqual(
            hashlib.sha256(
                _canonical_json_fixture(
                    list(ROLLOUT_LOG_VALIDATED_UNRETAINED)
                )
            ).hexdigest(),
            ROLLOUT_LOG_VALIDATED_UNRETAINED_SHA256,
        )
        projected = {native for native, _operation, _target
                     in ROLLOUT_LOG_PROJECTIONS}
        unretained = set(ROLLOUT_LOG_VALIDATED_UNRETAINED)
        self.assertFalse(projected & unretained)
        self.assertEqual(
            projected | unretained,
            set(PUFFER_RAW_LOG_KEYS),
        )
        self.assertEqual(authority["derived"], PROJECTION_COLLISIONS_DERIVATION)

    def test_flat_puffer_log_adapter_signature_and_one_event_reconciliation(
        self,
    ) -> None:
        signature = inspect.signature(
            self.protocol.normalize_puffer_integrity
        )
        self.assertEqual(
            tuple(signature.parameters),
            ("raw_log", "completed_summary", "endpoint_checks"),
        )
        self.assertEqual(
            signature.parameters["completed_summary"].kind,
            inspect.Parameter.KEYWORD_ONLY,
        )
        self.assertEqual(
            signature.parameters["endpoint_checks"].kind,
            inspect.Parameter.KEYWORD_ONLY,
        )
        raw = _valid_raw_log(
            objective_events=1,
            successful_episodes=1,
        )
        normalized = self.protocol.normalize_puffer_integrity(
            raw,
            completed_summary=_completed_summary(
                objective_events=1,
                successful_episodes=1,
            ),
            endpoint_checks=_endpoint_checks(),
        )
        self.assertEqual(normalized["objective"]["events"], 1)
        integrity = normalized["integrity"]
        validation = normalized["validation"]
        self.assertEqual(integrity["completed_episodes"], 2048)
        self.assertIs(type(integrity["completed_episodes"]), int)
        self.assertEqual(integrity["away_touchdowns"], 0)
        self.assertIs(type(integrity["away_touchdowns"]), int)
        self.assertEqual(integrity["mean_episode_length"], 8.0)
        self.assertEqual(integrity["reward_samples_per_episode"], 16)
        self.assertIs(
            type(integrity["reward_samples_per_episode"]),
            int,
        )
        self.assertEqual(integrity["reward_components"]["touchdown"], 1.0)
        self.assertEqual(integrity["reward_postclip_return"], 1.0)
        self.assertEqual(validation["total_touchdowns"], 1)
        self.assertEqual(validation["home_episode_return"], 1.0)
        self.assertEqual(validation["score_diff"], 1.0)
        self.assertEqual(
            validation["reward_episode_abs_max_mean"],
            1 / 2048,
        )
        self.assertEqual(integrity["projection_collisions"], 0)
        self.assertIs(type(integrity["projection_collisions"]), int)
        self.assertNotIn("projection_collisions", raw)

