    def test_flat_log_rejects_missing_extra_wrong_type_nonfinite_and_derived_key(
        self,
    ) -> None:
        summary = _completed_summary()
        checks = _endpoint_checks()
        mutations = []
        missing = _valid_raw_log()
        missing.pop("perf")
        mutations.append(("missing", missing))
        extra = _valid_raw_log()
        extra["extension"] = 0.0
        mutations.append(("extra", extra))
        derived = _valid_raw_log()
        derived["projection_collisions"] = 0.0
        mutations.append(("caller-derived", derived))
        for key in PUFFER_RAW_LOG_KEYS:
            integer = _valid_raw_log()
            integer[key] = 0
            mutations.append((f"integer:{key}", integer))
            boolean = _valid_raw_log()
            boolean[key] = False
            mutations.append((f"boolean:{key}", boolean))
        for key in ("n", "perf", "reward_component_touchdown"):
            for value in (math.nan, math.inf, -math.inf):
                nonfinite = _valid_raw_log()
                nonfinite[key] = value
                mutations.append((f"nonfinite:{key}:{value}", nonfinite))
        for name, raw in mutations:
            with self.subTest(name=name):
                with self.assertRaises(self.protocol.ProtocolError):
                    self.protocol.normalize_puffer_integrity(
                        raw,
                        completed_summary=summary,
                        endpoint_checks=checks,
                    )

    def test_flat_log_rejects_adjacent_binary32_counts_and_reconciliation_drift(
        self,
    ) -> None:
        below, exact, above = (
            struct.unpack("<f", struct.pack("<I", bits))[0]
            for bits in (0x39FFFFFF, 0x3A000000, 0x3A000001)
        )
        self.assertEqual(exact, 1 / 2048)
        self.assertLess(below, exact)
        self.assertGreater(above, exact)
        summary = _completed_summary(
            objective_events=1,
            successful_episodes=1,
        )
        for key in (
            "tds",
            "tds_t0",
            "episode_return",
            "score_diff",
            "reward_component_touchdown",
            "reward_postclip_return",
            "reward_episode_abs_max_mean",
        ):
            for value in (below, above):
                raw = _valid_raw_log(
                    objective_events=1,
                    successful_episodes=1,
                )
                raw[key] = value
                with self.subTest(key=key, bits=hex(
                    struct.unpack("<I", struct.pack("<f", value))[0]
                )):
                    with self.assertRaises(self.protocol.ProtocolError):
                        self.protocol.normalize_puffer_integrity(
                            raw,
                            completed_summary=summary,
                            endpoint_checks=_endpoint_checks(),
                        )
        nonintegral = _valid_raw_log()
        nonintegral["demo_episodes"] = 0.5 / 2048
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.normalize_puffer_integrity(
                nonintegral,
                completed_summary=_completed_summary(),
                endpoint_checks=_endpoint_checks(),
            )
        away = _valid_raw_log()
        away["tds_t1"] = exact
        away["tds"] = exact
        away["score_diff"] = -exact
        with self.assertRaises(self.protocol.ProtocolError):
            self.protocol.normalize_puffer_integrity(
                away,
                completed_summary=_completed_summary(),
                endpoint_checks=_endpoint_checks(),
            )

