    def test_adapter_canonicalizes_negative_zero_and_preserves_integer_types(
        self,
    ) -> None:
        raw = _valid_raw_log()
        for key, value in tuple(raw.items()):
            if value == 0.0:
                raw[key] = -0.0
        normalized = self.protocol.normalize_puffer_integrity(
            raw,
            completed_summary=_completed_summary(),
            endpoint_checks=_endpoint_checks(),
        )
        for value in _walk_numeric_values(normalized):
            if type(value) is float and value == 0.0:
                self.assertEqual(math.copysign(1.0, value), 1.0)
        for native, operation, target in ROLLOUT_LOG_PROJECTIONS:
            if operation in {
                "completed-count",
                "scale-nonnegative-integer",
                "retain-nonnegative-integer",
                "require-zero",
            } and target.startswith(("integrity.", "objective.")):
                value = _nested_value(normalized, target)
                self.assertIs(
                    type(value),
                    int,
                    f"{native} -> {target} must remain JSON integer",
                )

