    def test_rollout_alignment_error_owns_bounded_bitset_and_fault_order(
        self,
    ) -> None:
        def expected_rollout(check, delayed_row, agent_rows):
            payload = bytearray(512)
            for agent_row in agent_rows:
                payload[agent_row // 8] |= 1 << (agent_row % 8)
            return {
                "agent_row_count": len(agent_rows),
                "agent_rows_bitset_hex": bytes(payload).hex(),
                "check": check,
                "delayed_row": delayed_row,
                "mode": "training",
            }

        def require_error(collector, expected):
            with self.assertRaises(
                self.protocol.RolloutAlignmentError
            ) as caught:
                self.protocol.validate_live_rollout(
                    collector,
                    mode="training",
                )
            self.assertEqual(caught.exception.rollout, expected)
            self.assertEqual(
                tuple(sorted(caught.exception.rollout)),
                ROLLOUT_FAILURE_FIELDS,
            )
            encoded = caught.exception.rollout["agent_rows_bitset_hex"]
            self.assertEqual(len(encoded), 1024)
            self.assertRegex(encoded, r"^[0-9a-f]{1024}$")
            self.assertEqual(
                sum(byte.bit_count() for byte in bytes.fromhex(encoded)),
                caught.exception.rollout["agent_row_count"],
            )

        asymmetric = _FakeCollector(mode="training")
        asymmetric.terminals[1][4:6] = [0, 1]
        asymmetric.terminals[1][20:22] = [1, 0]
        asymmetric.terminals[3][0:2] = [1, 0]
        asymmetric.terminals[0][100:102] = [1, 1]
        require_error(
            asymmetric,
            expected_rollout(
                "home-away-terminal-asymmetry",
                1,
                (4, 5, 20, 21),
            ),
        )

        row_zero = _FakeCollector(mode="training")
        row_zero.terminals[0][0:2] = [1, 1]
        row_zero.terminals[2][4:6] = [1, 1]
        require_error(
            row_zero,
            expected_rollout("row-zero-canary", 0, (0, 1)),
        )

        early = _FakeCollector(mode="training")
        early.terminals[2][0:2] = [1, 1]
        early.terminals[4][2:4] = [1, 1]
        early.tail_terminals[4:6] = [0, 0]
        require_error(
            early,
            expected_rollout("early-terminal", 2, (0, 1)),
        )

        tail = _FakeCollector(mode="training")
        tail.tail_terminals[0:2] = [0, 0]
        tail.tail_terminals[4094:4096] = [0, 0]
        require_error(
            tail,
            expected_rollout(
                "tail-terminal",
                8,
                (0, 1, 4094, 4095),
            ),
        )

