    def test_reference_action_triples_are_not_embedded_or_imported(
        self,
    ) -> None:
        header_path = (
            ROOT / "puffer/bloodbowl/f5_trainability_fixture.generated.h"
        )
        header = header_path.read_text(encoding="ascii")
        match = re.search(
            (
                r"BBE_F5_TRAINABILITY_REFERENCE_ACTIONS"
                r"\s*\[\s*8\s*\]\s*\[\s*3\s*\]\s*=\s*\{"
                r"(?P<body>.*?)\};"
            ),
            header,
            flags=re.DOTALL,
        )
        self.assertIsNotNone(match)
        triples = tuple(
            tuple(int(value) for value in values)
            for values in re.findall(
                r"\{\s*(\d+)u,\s*(\d+)u,\s*(\d+)u\s*\}",
                match.group("body"),
            )
        )
        self.assertEqual(len(triples), 8)
        self.assertTrue(all(len(triple) == 3 for triple in triples))
        flattened = tuple(value for triple in triples for value in triple)

        for relative in IMPLEMENTATION_SURFACES[1:]:
            source = (ROOT / relative).read_text(encoding="utf-8")
            lowered = source.lower()
            with self.subTest(relative=relative, form="source-import"):
                self.assertNotIn(
                    "f5_trainability_fixture.generated.h",
                    lowered,
                )
                self.assertNotIn(
                    "bbe_f5_trainability_reference_actions",
                    lowered,
                )
                self.assertNotIn(
                    "456e336e5eaa92e4e5fdedfb753d237a"
                    "163e9a8e4e58ff09fa8979d2a91f4300",
                    lowered,
                )

            tree = ast.parse(source)
            literal_sequences = []
            for node in ast.walk(tree):
                if not isinstance(node, (ast.List, ast.Tuple)):
                    continue
                values = []
                for element in node.elts:
                    if (
                        isinstance(element, ast.Constant)
                        and type(element.value) is int
                    ):
                        values.append(element.value)
                    else:
                        break
                else:
                    literal_sequences.append(tuple(values))
            with self.subTest(relative=relative, form="nested"):
                self.assertTrue(
                    all(
                        sequence not in triples
                        for sequence in literal_sequences
                    )
                )
            with self.subTest(relative=relative, form="flattened"):
                self.assertNotIn(flattened, literal_sequences)
            for triple in triples:
                pattern = r"(?<!\d)" + r"\s*,\s*".join(
                    str(value) for value in triple
                ) + r"(?!\d)"
                with self.subTest(
                    relative=relative,
                    form="text-triple",
                    triple=triple,
                ):
                    self.assertIsNone(re.search(pattern, source))

    def test_model_construction_order_and_digest_oracles_are_frozen(self) -> None:
        protocol = _protocol()
        runner_source = pathlib.Path(_runner().__file__).read_text(
            encoding="utf-8"
        )
        tree = ast.parse(runner_source)
        expected = {
            "network": "models.MinGRU",
            "encoder": "models.DefaultEncoder",
            "decoder": "models.DefaultDecoder",
            "policy": "models.Policy",
        }
        assignments = {}
        for node in ast.walk(tree):
            if not isinstance(node, ast.Assign) or len(node.targets) != 1:
                continue
            target = node.targets[0]
            if not isinstance(target, ast.Name) or target.id not in expected:
                continue
            if not isinstance(node.value, ast.Call):
                continue
            assignments.setdefault(target.id, []).append(node)
        self.assertEqual(set(assignments), set(expected))
        ordered_nodes = []
        for target, call_name in expected.items():
            with self.subTest(target=target):
                self.assertEqual(len(assignments[target]), 1)
                assignment = assignments[target][0]
                self.assertEqual(_ast_call_name(assignment.value), call_name)
                ordered_nodes.append(assignment)
        self.assertEqual(
            [node.lineno for node in ordered_nodes],
            sorted(node.lineno for node in ordered_nodes),
        )
        policy_call = assignments["policy"][0].value
        self.assertEqual(
            [
                argument.id
                for argument in policy_call.args
                if isinstance(argument, ast.Name)
            ],
            ["encoder", "decoder", "network"],
        )
        construction_functions = []
        for function in (
            node
            for node in ast.walk(tree)
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        ):
            function_assignments = {
                target.id
                for node in ast.walk(function)
                if isinstance(node, ast.Assign)
                and len(node.targets) == 1
                and isinstance((target := node.targets[0]), ast.Name)
                and target.id in expected
                and isinstance(node.value, ast.Call)
            }
            if function_assignments:
                construction_functions.append(
                    (function, function_assignments)
                )
        self.assertEqual(len(construction_functions), 1)
        self.assertEqual(
            construction_functions[0][1],
            set(expected),
        )
        all_call_names = [
            _ast_call_name(node)
            for node in ast.walk(tree)
            if isinstance(node, ast.Call)
        ]
        self.assertEqual(all_call_names.count("_C.create_vec"), 1)
        self.assertEqual(all_call_names.count("torch_pufferl.PuffeRL"), 1)
        self.assertEqual(
            protocol.EXPECTED_INITIAL_PARAMETER_SHA256,
            EXPECTED_INITIAL_PARAMETER_SHA256,
        )
        self.assertEqual(
            protocol.EXPECTED_INITIAL_RAW_SHA256,
            EXPECTED_INITIAL_RAW_SHA256,
        )
        self.assertEqual(
            protocol.WRONG_ORDER_PARAMETER_SHA256,
            WRONG_ORDER_PARAMETER_SHA256,
        )
        self.assertEqual(
            protocol.EXPECTED_ONE_UPDATE_PARAMETER_SHA256,
            EXPECTED_ONE_UPDATE_PARAMETER_SHA256,
        )
        protocol.validate_initial_parameter_sha256(
            EXPECTED_INITIAL_PARAMETER_SHA256
        )
        for invalid in (
            WRONG_ORDER_PARAMETER_SHA256,
            EXPECTED_ONE_UPDATE_PARAMETER_SHA256,
            "0" * 64,
        ):
            with self.subTest(invalid=invalid):
                with self.assertRaises(protocol.ProtocolError):
                    protocol.validate_initial_parameter_sha256(invalid)

    def test_ast_rollout_gate_train_order_is_exact_and_single_site(self) -> None:
        tree = ast.parse(
            pathlib.Path(_runner().__file__).read_text(encoding="utf-8")
        )
        candidates = []
        for function in (
            node
            for node in ast.walk(tree)
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        ):
            calls = [
                node
                for node in ast.walk(function)
                if isinstance(node, ast.Call)
            ]
            names = [_ast_call_name(call) for call in calls]
            if any(name and name.endswith(".rollouts") for name in names):
                candidates.append((function, calls, names))
        self.assertEqual(len(candidates), 1)
        _function, calls, names = candidates[0]

        def exact_calls(predicate):
            return [
                call
                for call in calls
                if predicate(_ast_call_name(call))
            ]

        rollout = exact_calls(
            lambda name: bool(name and name.endswith(".rollouts"))
        )
        gate = exact_calls(
            lambda name: name in {
                "protocol.validate_live_rollout",
                "validate_live_rollout",
            }
        )
        train = exact_calls(
            lambda name: bool(name and name.endswith(".train"))
        )
        self.assertEqual(len(rollout), 1)
        self.assertEqual(len(gate), 1)
        self.assertEqual(len(train), 1)
        self.assertLess(rollout[0].lineno, gate[0].lineno)
        self.assertLess(gate[0].lineno, train[0].lineno)

    def test_all_rollout_populations_cross_the_flat_log_adapter(self) -> None:
        protocol_tree = ast.parse(
            pathlib.Path(_protocol().__file__).read_text(encoding="utf-8")
        )
        validator = next(
            node
            for node in protocol_tree.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name == "validate_live_rollout"
        )
        normalization_calls = [
            node
            for node in ast.walk(validator)
            if isinstance(node, ast.Call)
            and _ast_call_name(node)
            in {
                "normalize_puffer_integrity",
                "protocol.normalize_puffer_integrity",
            }
        ]
        self.assertEqual(len(normalization_calls), 1)
        for module, population in (
            (_runner(), "controller-training-and-evaluation"),
            (_verifier(), "verifier-replay"),
        ):
            tree = ast.parse(
                pathlib.Path(module.__file__).read_text(encoding="utf-8")
            )
            drivers = []
            for function in (
                node
                for node in ast.walk(tree)
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            ):
                calls = [
                    node
                    for node in ast.walk(function)
                    if isinstance(node, ast.Call)
                ]
                rollout_calls = [
                    call
                    for call in calls
                    if (_ast_call_name(call) or "").endswith(".rollouts")
                ]
                if not rollout_calls:
                    continue
                gate_calls = [
                    call
                    for call in calls
                    if _ast_call_name(call)
                    in {
                        "protocol.validate_live_rollout",
                        "validate_live_rollout",
                    }
                ]
                drivers.append((rollout_calls, gate_calls))
            with self.subTest(population=population):
                self.assertGreaterEqual(len(drivers), 1)
                for rollout_calls, gate_calls in drivers:
                    self.assertEqual(len(rollout_calls), 1)
                    self.assertEqual(len(gate_calls), 1)
                    self.assertLess(
                        rollout_calls[0].lineno,
                        gate_calls[0].lineno,
                    )

    def test_final_consumer_phase_signatures_and_success_order_are_exact(
        self,
    ) -> None:
        verifier = _verifier()
        expected_signatures = (
            (
                verifier._run_final_consumer_preflight,
                (
                    "operations",
                    "artifact_dir",
                    "expected_verdict_sha256",
                ),
            ),
            (
                verifier._load_authenticated_protocol_helper,
                ("operations", "context"),
            ),
            (
                verifier._run_final_consumer_postflight,
                ("operations", "context"),
            ),
            (
                verifier._consume_final,
                (
                    "operations",
                    "artifact_dir",
                    "expected_verdict_sha256",
                ),
            ),
        )
        for function, names in expected_signatures:
            with self.subTest(function=function.__name__):
                signature = inspect.signature(function)
                self.assertEqual(tuple(signature.parameters), names)
                for name in names[1:]:
                    self.assertEqual(
                        signature.parameters[name].kind,
                        inspect.Parameter.KEYWORD_ONLY,
                    )

        events = []
        context = object()
        returned = object()
        authenticated = _AuthenticatedProtocolProbe(
            events,
            result=returned,
        )
        operations = _FinalConsumerPhaseProbe(events)
        originals = {
            name: getattr(verifier, name)
            for name in (
                "_run_final_consumer_preflight",
                "_load_authenticated_protocol_helper",
                "_run_final_consumer_postflight",
            )
        }
        try:
            def preflight(_operations, **_kwargs):
                events.append("preflight")
                return context

            def load(_operations, *, context):
                events.append(("load-held-fd", context))
                return authenticated

            def postflight(_operations, *, context):
                events.append(("postflight", context))

            verifier._run_final_consumer_preflight = preflight
            verifier._load_authenticated_protocol_helper = load
            verifier._run_final_consumer_postflight = postflight
            result = verifier._consume_final(
                operations,
                artifact_dir="/external/pilot",
                expected_verdict_sha256="d" * 64,
            )
        finally:
            for name, original in originals.items():
                setattr(verifier, name, original)
        self.assertIs(result, returned)
        self.assertEqual(
            events,
            [
                "preflight",
                ("marker", context),
                ("load-held-fd", context),
                (
                    "validate_final_evidence",
                    "/external/pilot",
                    "d" * 64,
                ),
                ("postflight", context),
            ],
        )

    def test_final_consumer_exception_at_each_phase_short_circuits(
        self,
    ) -> None:
        verifier = _verifier()
        phase_order = (
            "preflight",
            "marker",
            "loader",
            "validator",
            "postflight",
        )
        originals = {
            name: getattr(verifier, name)
            for name in (
                "_run_final_consumer_preflight",
                "_load_authenticated_protocol_helper",
                "_run_final_consumer_postflight",
            )
        }
        try:
            for failed_phase in phase_order:
                events = []
                context = object()
                authenticated = _AuthenticatedProtocolProbe(
                    events,
                    result=object(),
                    fail=failed_phase == "validator",
                )
                operations = _FinalConsumerPhaseProbe(
                    events,
                    fail_marker=failed_phase == "marker",
                )

                def preflight(_operations, **_kwargs):
                    events.append("preflight")
                    if failed_phase == "preflight":
                        raise _InjectedPublicationFailure("preflight")
                    return context

                def load(_operations, *, context):
                    events.append("loader")
                    if failed_phase == "loader":
                        raise _InjectedPublicationFailure("loader")
                    return authenticated

                def postflight(_operations, *, context):
                    events.append("postflight")
                    if failed_phase == "postflight":
                        raise _InjectedPublicationFailure("postflight")

                verifier._run_final_consumer_preflight = preflight
                verifier._load_authenticated_protocol_helper = load
                verifier._run_final_consumer_postflight = postflight
                with self.subTest(failed_phase=failed_phase):
                    with self.assertRaises(_InjectedPublicationFailure):
                        verifier._consume_final(
                            operations,
                            artifact_dir="/external/pilot",
                            expected_verdict_sha256="d" * 64,
                        )
                    event_names = [
                        (
                            (
                                "validator"
                                if event[0]
                                == "validate_final_evidence"
                                else event[0]
                            )
                            if isinstance(event, tuple)
                            else event
                        )
                        for event in events
                    ]
                    failed_index = phase_order.index(failed_phase)
                    expected_prefix = list(phase_order[: failed_index + 1])
                    self.assertEqual(event_names, expected_prefix)
        finally:
            for name, original in originals.items():
                setattr(verifier, name, original)

    def test_final_consumer_preflight_cannot_execute_helper_before_marker(
        self,
    ) -> None:
        verifier_tree = ast.parse(
            pathlib.Path(_verifier().__file__).read_text(encoding="utf-8")
        )

        def function(name):
            return next(
                node
                for node in verifier_tree.body
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                and node.name == name
            )

        preflight = function("_run_final_consumer_preflight")
        preflight_calls = {
            _ast_call_name(node)
            for node in ast.walk(preflight)
            if isinstance(node, ast.Call)
        }
        forbidden_preflight = {
            "compile",
            "exec",
            "__import__",
            "importlib.import_module",
            "runpy.run_path",
            "types.ModuleType",
        }
        self.assertFalse(preflight_calls & forbidden_preflight)

        loader = function("_load_authenticated_protocol_helper")
        loader_calls = [
            _ast_call_name(node)
            for node in ast.walk(loader)
            if isinstance(node, ast.Call)
        ]
        self.assertEqual(loader_calls.count("compile"), 1)
        self.assertEqual(loader_calls.count("exec"), 1)
        self.assertEqual(loader_calls.count("types.ModuleType"), 1)
        self.assertFalse(
            {
                "open",
                "pathlib.Path.read_bytes",
                "importlib.import_module",
                "runpy.run_path",
            }
            & set(loader_calls)
        )
        self.assertIn(
            "f5_recurrent_ppo_protocol_authenticated",
            {
                node.value
                for node in ast.walk(loader)
                if isinstance(node, ast.Constant)
                and isinstance(node.value, str)
            },
        )

        consumer = function("_consume_final")
        fixed_phase_names = {
                "_run_final_consumer_preflight",
                "operations.mark_preflight_complete",
                "_load_authenticated_protocol_helper",
                "_run_final_consumer_postflight",
        }
        line_order = []
        for node in ast.walk(consumer):
            if not isinstance(node, ast.Call):
                continue
            name = _ast_call_name(node)
            if name in fixed_phase_names:
                line_order.append((node.lineno, name))
            elif (name or "").endswith(".validate_final_evidence"):
                line_order.append(
                    (node.lineno, "module.validate_final_evidence")
                )
        self.assertEqual(
            [name for _line, name in sorted(line_order)],
            [
                "_run_final_consumer_preflight",
                "operations.mark_preflight_complete",
                "_load_authenticated_protocol_helper",
                "module.validate_final_evidence",
                "_run_final_consumer_postflight",
            ],
        )

    def test_protocol_helper_remains_python39_stdlib_only(self) -> None:
        source = pathlib.Path(_protocol().__file__).read_text(
            encoding="utf-8"
        )
        tree = ast.parse(source, feature_version=(3, 9))
        imported_roots = set()
        for node in tree.body:
            if isinstance(node, ast.Import):
                imported_roots.update(
                    alias.name.split(".", 1)[0]
                    for alias in node.names
                )
            elif isinstance(node, ast.ImportFrom):
                self.assertGreaterEqual(node.level, 0)
                if node.level:
                    self.fail("protocol helper may not use local imports")
                imported_roots.add((node.module or "").split(".", 1)[0])
        self.assertTrue(
            imported_roots
            <= (set(sys.stdlib_module_names) | {"__future__"})
        )
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and _ast_call_name(node) == "zip":
                self.assertNotIn(
                    "strict",
                    {keyword.arg for keyword in node.keywords},
                )
            annotations = []
            if isinstance(node, ast.arg) and node.annotation is not None:
                annotations.append(node.annotation)
            elif isinstance(node, ast.AnnAssign):
                annotations.append(node.annotation)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if node.returns is not None:
                    annotations.append(node.returns)
            for annotation in annotations:
                self.assertFalse(
                    any(
                        isinstance(child, ast.BinOp)
                        and isinstance(child.op, ast.BitOr)
                        for child in ast.walk(annotation)
                    ),
                    "PEP 604 annotations are not CPython 3.9 compatible",
                )

