    def _advance_turns(
        self,
        turns,
        current,
        target,
        **ready,
    ):
        while current + SIGNAL_RESPONSE_POLL_NANOSECONDS < target:
            current += SIGNAL_RESPONSE_POLL_NANOSECONDS
            turns.append({"advance_to": current})
        turns.append({"advance_to": target, **ready})
        return target

    def _assert_hybrid_reactor_catalog(self):
        self.assertEqual(
            tuple(
                label
                for label, _owners, _mode in _HYBRID_REACTOR_CASES
            ),
            (
                "R1-real-saturated-job-pipe-recovers",
                "R2-real-saturated-training-stdout-drains",
                "R3-real-saturated-job-pipe-reaches-deadline",
                "S1-exact-f5-completion-tie-rejects",
                "S2-exact-poll-timeout-minimum",
            ),
        )
        self.assertEqual(len(_HYBRID_REACTOR_CASES), 5)
        self.assertEqual(
            len(
                {
                    label
                    for label, _owners, _mode
                    in _HYBRID_REACTOR_CASES
                }
            ),
            5,
        )
        applications = tuple(
            (label, owner, mode)
            for label, owners, mode in _HYBRID_REACTOR_CASES
            for owner in owners
        )
        self.assertEqual(len(applications), 9)
        self.assertEqual(
            collections.Counter(
                owner for _label, owner, _mode in applications
            ),
            collections.Counter({"C": 4, "V": 4, "T": 1}),
        )
        self.assertEqual(
            collections.Counter(
                mode for _label, _owner, mode in applications
            ),
            collections.Counter({"real-posix": 5, "scripted": 4}),
        )
        self.assertEqual(
            collections.Counter(
                label for label, _owner, _mode in applications
            ),
            collections.Counter(
                {
                    "R1-real-saturated-job-pipe-recovers": 2,
                    "R2-real-saturated-training-stdout-drains": 1,
                    "R3-real-saturated-job-pipe-reaches-deadline": 2,
                    "S1-exact-f5-completion-tie-rejects": 2,
                    "S2-exact-poll-timeout-minimum": 2,
                }
            ),
        )
        return applications

