    def test_typed_worker_failure_and_exit_table_matrix(self) -> None:
        valid_specifications = []
        reject_specifications = []
        exit_by_status = {
            "integrity-abort": 70,
            "resource-truncated": 75,
        }
        rollout_checks = (
            "row-zero-canary",
            "early-terminal",
            "tail-terminal",
            "home-away-terminal-asymmetry",
        )

        def rollout(check, *, agent_rows=None, delayed_row=None):
            defaults = {
                "row-zero-canary": (0, (0, 1)),
                "early-terminal": (1, (0, 1)),
                "tail-terminal": (8, (4094, 4095)),
                "home-away-terminal-asymmetry": (1, (4, 5, 20, 21)),
            }
            self.assertIn(check, defaults)
            default_row, default_agents = defaults[check]
            selected_row = default_row if delayed_row is None else delayed_row
            selected_agents = (
                default_agents if agent_rows is None else tuple(agent_rows)
            )
            bitset = bytearray(512)
            for agent_row in selected_agents:
                self.assertIs(type(agent_row), int)
                self.assertIn(agent_row, range(4096))
                bitset[agent_row // 8] |= 1 << (agent_row % 8)
            encoded = bytes(bitset).hex()
            self.assertEqual(len(encoded), 1024)
            self.assertRegex(encoded, r"^[0-9a-f]{1024}$")
            self.assertEqual(
                sum(byte.bit_count() for byte in bytes.fromhex(encoded)),
                len(set(selected_agents)),
            )
            return {
                "agent_row_count": len(set(selected_agents)),
                "agent_rows_bitset_hex": encoded,
                "check": check,
                "delayed_row": selected_row,
                "mode": "training",
            }

        def progress(
            committed_epoch,
            *,
            attempted=False,
            rollout_record=None,
        ):
            self.assertIs(type(committed_epoch), int)
            self.assertIn(committed_epoch, range(2957))
            accepted = committed_epoch * 32768
            return {
                "accepted_global_agent_step": accepted,
                "attempted_update_index": (
                    committed_epoch if attempted else None
                ),
                "committed_epoch": committed_epoch,
                "learner_disposition": "discarded",
                "rollout": copy.deepcopy(rollout_record),
                "volatile_global_agent_step": (
                    accepted + 32768 if attempted else accepted
                ),
            }

        combinations = {
            combination[:4]: combination
            for combination in WORKER_FAILURE_COMBINATIONS
        }
        self.assertEqual(len(combinations), 24)

        def combination(worker_kind, status, phase, cause):
            key = (worker_kind, status, phase, cause)
            self.assertIn(key, combinations)
            return combinations[key]

        def valid_record(fixture, selected, *, rollout_check=None):
            worker_kind, status, phase, cause, progress_required = selected
            self.assertEqual(fixture["job"]["worker_kind"], worker_kind)
            if progress_required:
                self.assertEqual(worker_kind, "training")
                if phase == "serialization":
                    progress_record = progress(2956)
                elif cause == "rollout-alignment":
                    self.assertIn(rollout_check, rollout_checks)
                    progress_record = progress(
                        1,
                        attempted=True,
                        rollout_record=rollout(rollout_check),
                    )
                elif cause in {"runtime-contract", "training-deadline"}:
                    progress_record = progress(1, attempted=True)
                elif cause == "worker-resource":
                    progress_record = progress(2)
                else:
                    progress_record = progress(1)
            else:
                self.assertIsNone(rollout_check)
                progress_record = None
            record = {
                "cause": cause,
                "job_sha256": _test_worker_job_sha256(fixture["job"]),
                "nonce": fixture["job"]["nonce"],
                "phase": phase,
                "progress": progress_record,
                "schema": "bloodbowl-f5-worker-failure-v1",
                "status": status,
                "worker_kind": worker_kind,
            }
            self.assertEqual(
                tuple(sorted(record)),
                WORKER_FAILURE_FIELDS,
            )
            if progress_record is not None:
                self.assertEqual(
                    tuple(sorted(progress_record)),
                    WORKER_PROGRESS_FIELDS,
                )
                if progress_record["rollout"] is not None:
                    self.assertEqual(
                        tuple(sorted(progress_record["rollout"])),
                        ROLLOUT_FAILURE_FIELDS,
                    )
            self.assertLessEqual(len(_canonical_json_fixture(record)), 4096)
            return record

        def mapped_failure(selected):
            worker_kind, status, _phase, cause, _progress_required = selected
            if worker_kind == "training" and cause == "training-deadline":
                return "resource-truncated", "training-deadline"
            if cause == "worker-resource":
                return "resource-truncated", "worker-resource"
            if worker_kind == "training" and cause == "rollout-alignment":
                return "integrity-abort", "rollout-alignment"
            self.assertEqual(status, "integrity-abort")
            return "integrity-abort", "worker-contract"

        def failure_outcome(
            frame,
            record,
            exit_code,
            *,
            promoted_progress=None,
        ):
            self.assertEqual(frame["payload"], _canonical_json_fixture(record))
            self.assertLessEqual(len(frame["payload"]), 4096)
            return {
                "child_state": ("exit", exit_code),
                "expected_progress": copy.deepcopy(promoted_progress),
                "expected_spool_payloads": (frame["payload"],),
                "postflight": True,
                "stderr_chunks": (_PIPE_EOF,),
                "stdout_chunks": (frame["wire"], _PIPE_EOF),
            }

        def make_valid_builder(selected, rollout_check=None):
            def build(fixture):
                record = valid_record(
                    fixture,
                    selected,
                    rollout_check=rollout_check,
                )
                frame = _test_build_worker_failure_frame(
                    fixture,
                    record=record,
                )
                return failure_outcome(
                    frame,
                    record,
                    exit_by_status[record["status"]],
                    promoted_progress=record["progress"],
                )

            return build

        def make_mutation_builder(
            selected,
            mutation,
            *,
            rollout_check=None,
            pinned_exit=None,
        ):
            def build(fixture):
                source = valid_record(
                    fixture,
                    selected,
                    rollout_check=rollout_check,
                )
                source_snapshot = copy.deepcopy(source)
                request = mutation(copy.deepcopy(source))
                self.assertEqual(
                    set(request),
                    set(request) & {
                        "additions",
                        "removals",
                        "replacements",
                    },
                )
                record, frame = _test_mutate_canonical_worker_failure(
                    fixture,
                    source,
                    replacements=request.get("replacements"),
                    removals=request.get("removals", ()),
                    additions=request.get("additions"),
                )
                self.assertEqual(source, source_snapshot)
                exit_code = pinned_exit
                if exit_code is None:
                    self.assertIn(record.get("status"), exit_by_status)
                    exit_code = exit_by_status[record["status"]]
                return failure_outcome(frame, record, exit_code)

            return build

