        def raw_root_builder(kind):
            def build(fixture):
                source = valid_record(fixture, evaluation_integrity)
                canonical = _canonical_json_fixture(source)
                if kind == "duplicate-root-key":
                    singleton = _canonical_json_fixture(
                        {"cause": source["cause"]}
                    )
                    duplicate_leaf = singleton[1:-2]
                    self.assertTrue(
                        canonical.startswith(b"{" + duplicate_leaf + b",")
                    )
                    raw = b"{" + duplicate_leaf + b"," + canonical[1:]
                    self.assertEqual(json.loads(raw), source)
                    self.assertEqual(
                        raw.count(b'"cause"'),
                        canonical.count(b'"cause"') + 1,
                    )
                    self.assertNotEqual(raw, canonical)
                elif kind == "canonical-list-root":
                    raw = b"[]\n"
                    self.assertEqual(json.loads(raw), [])
                    self.assertEqual(raw, _canonical_json_fixture([]))
                else:
                    raise AssertionError("unowned raw worker-failure root")
                frame = _test_build_worker_failure_frame(
                    fixture,
                    raw_payload=raw,
                )
                self.assertEqual(frame["payload"], raw)
                return {
                    "child_state": ("exit", 70),
                    "expected_progress": None,
                    "expected_spool_payloads": (raw,),
                    "postflight": True,
                    "stderr_chunks": (_PIPE_EOF,),
                    "stdout_chunks": (frame["wire"], _PIPE_EOF),
                }

            return build

