        def stream_builder(mode):
            def build(fixture):
                integrity_record = valid_record(
                    fixture,
                    evaluation_integrity,
                )
                integrity_frame = _test_build_worker_failure_frame(
                    fixture,
                    record=integrity_record,
                )
                resource_record = valid_record(
                    fixture,
                    evaluation_bootstrap_resource,
                )
                resource_frame = _test_build_worker_failure_frame(
                    fixture,
                    record=resource_record,
                )
                if mode == "zero-frames-exit-70":
                    return {
                        "child_state": ("exit", 70),
                        "expected_progress": None,
                        "expected_spool_payloads": (),
                        "postflight": True,
                        "stderr_chunks": (_PIPE_EOF,),
                        "stdout_chunks": (_PIPE_EOF,),
                    }
                if mode == "success-exit-70":
                    return {
                        "child_state": ("exit", 70),
                        "expected_progress": None,
                        "expected_spool_payloads": tuple(fixture["payloads"]),
                        "postflight": True,
                        "stderr_chunks": (_PIPE_EOF,),
                        "stdout_chunks": (
                            *(frame["wire"] for frame in fixture["frames"]),
                            _PIPE_EOF,
                        ),
                    }
                if mode in {
                    "integrity-exit-75",
                    "failure-exit-0",
                    "failure-exit-1",
                }:
                    exit_code = {
                        "integrity-exit-75": 75,
                        "failure-exit-0": 0,
                        "failure-exit-1": 1,
                    }[mode]
                    return failure_outcome(
                        integrity_frame,
                        integrity_record,
                        exit_code,
                    )
                if mode == "resource-exit-70":
                    return failure_outcome(
                        resource_frame,
                        resource_record,
                        70,
                    )
                if mode == "success-then-failure":
                    return {
                        "child_state": ("exit", 0),
                        "expected_progress": None,
                        "expected_spool_payloads": (fixture["payloads"][0],),
                        "postflight": False,
                        "stderr_chunks": (_PIPE_EOF,),
                        "stdout_chunks": (
                            fixture["frames"][0]["wire"],
                            integrity_frame["wire"],
                            _PIPE_EOF,
                        ),
                    }
                if mode == "two-failures":
                    return {
                        "child_state": ("exit", 70),
                        "expected_progress": None,
                        "expected_spool_payloads": (
                            integrity_frame["payload"],
                        ),
                        "postflight": False,
                        "stderr_chunks": (_PIPE_EOF,),
                        "stdout_chunks": (
                            integrity_frame["wire"],
                            integrity_frame["wire"],
                            _PIPE_EOF,
                        ),
                    }
                if mode == "same-turn-signal":
                    return {
                        "child_state": ("signal", signal.SIGSEGV),
                        "expected_progress": None,
                        "expected_spool_payloads": (),
                        "postflight": False,
                        "stderr_chunks": (_PIPE_EOF,),
                        "stdout_chunks": (
                            integrity_frame["wire"],
                            _PIPE_EOF,
                        ),
                    }
                raise AssertionError("unowned failure stream/exit mode")

            return build

