    def test_handoff_pipe_rejects_4097_noncanonical_bad_schema_and_bad_fields(
        self,
    ) -> None:
        record = _controller_handoff_record()
        noncanonical = json.dumps(record, indent=2).encode("ascii") + b"\n"
        duplicate = (
            b'{"schema":"' + CONTROLLER_HANDOFF_SCHEMA.encode("ascii")
            + b'","schema":"' + CONTROLLER_HANDOFF_SCHEMA.encode("ascii")
            + b'"}\n'
        )
        invalid_frames = (
            struct.pack(">I", 0),
            struct.pack(">I", 4097) + bytes(4097),
            struct.pack(">I", len(noncanonical)) + noncanonical,
            struct.pack(">I", len(duplicate)) + duplicate,
        )
        for frame in invalid_frames:
            with self.subTest(length=len(frame)):
                with self.assertRaises(self.protocol.ProtocolError):
                    self._read_handoff(frame)
        canonical = _canonical_json_fixture(record)
        frame = struct.pack(">I", len(canonical)) + canonical
        for overrides in (
            {"expected_schema": VERDICT_HANDOFF_SCHEMA},
            {
                "expected_fields": (
                    *CONTROLLER_HANDOFF_FIELDS,
                    "extension",
                )
            },
        ):
            with self.subTest(overrides=overrides):
                with self.assertRaises(self.protocol.ProtocolError):
                    self._read_handoff(frame, **overrides)

    def test_handoff_pipe_uses_remaining_deadline_for_header_body_and_eof(
        self,
    ) -> None:
        canonical = _canonical_json_fixture(_controller_handoff_record())
        cases = (
            (b"", (False,)),
            (
                struct.pack(">I", len(canonical)) + canonical[:8],
                (True, True, False),
            ),
            (
                struct.pack(">I", len(canonical)) + canonical,
                (True, True, False),
            ),
        )
        for payload, responses in cases:
            response_iterator = iter(responses)

            def wait_readable(_fd, remaining):
                self.assertGreater(remaining, 0.0)
                return next(response_iterator, False)

            with self.subTest(stage_count=len(responses)):
                with self.assertRaises(self.protocol.ProtocolError):
                    self._read_handoff(
                        payload,
                        keep_writer=True,
                        deadline=20.0,
                        monotonic=lambda: 19.0,
                        wait_readable=wait_readable,
                    )
        with self.assertRaises(self.protocol.ProtocolError):
            self._read_handoff(
                b"",
                keep_writer=True,
                deadline=20.0,
                monotonic=lambda: 20.0,
                wait_readable=lambda _fd, _remaining: self.fail(
                    "expired deadline must fail before waiting"
                ),
            )

    def test_ack_pipe_requires_exact_literal_digest_lf_and_eof(self) -> None:
        canonical = _canonical_json_fixture(_controller_handoff_record())
        ack = (
            PUBLICATION_ACK_PREFIX
            + hashlib.sha256(canonical).hexdigest().encode("ascii")
            + b"\n"
        )
        self.assertEqual(self.protocol.publication_ack(canonical), ack)
        read_fd, write_fd = _pipe_containing(ack, close_writer=True)
        try:
            self.protocol.read_publication_ack_channel(
                read_fd,
                deadline=time.monotonic() + 2.0,
                canonical_record_bytes=canonical,
                monotonic=time.monotonic,
                wait_readable=_wait_readable,
            )
        finally:
            _close_fd(write_fd)
            _close_fd(read_fd)

    def test_ack_pipe_rejects_empty_short_wrong_hash_literal_extra_and_timeout(
        self,
    ) -> None:
        canonical = _canonical_json_fixture(_controller_handoff_record())
        ack = (
            PUBLICATION_ACK_PREFIX
            + hashlib.sha256(canonical).hexdigest().encode("ascii")
            + b"\n"
        )
        invalid = (
            b"",
            ack[:-1],
            PUBLICATION_ACK_PREFIX + (b"0" * 64) + b"\n",
            b"bloodbowl-f5-publication-ack-v0 " + ack.split(b" ", 1)[1],
            ack + b"x",
            ack + b"\n",
        )
        for payload in invalid:
            read_fd, write_fd = _pipe_containing(
                payload,
                close_writer=True,
            )
            try:
                with self.subTest(length=len(payload)):
                    with self.assertRaises(self.protocol.ProtocolError):
                        self.protocol.read_publication_ack_channel(
                            read_fd,
                            deadline=time.monotonic() + 2.0,
                            canonical_record_bytes=canonical,
                            monotonic=time.monotonic,
                            wait_readable=_wait_readable,
                        )
            finally:
                _close_fd(write_fd)
                _close_fd(read_fd)
        read_fd, write_fd = _pipe_containing(b"", close_writer=False)
        try:
            with self.assertRaises(self.protocol.ProtocolError):
                self.protocol.read_publication_ack_channel(
                    read_fd,
                    deadline=1.0,
                    canonical_record_bytes=canonical,
                    monotonic=lambda: 1.0,
                    wait_readable=lambda _fd, _remaining: False,
                )
        finally:
            _close_fd(write_fd)
            _close_fd(read_fd)
        read_fd, write_fd = _pipe_containing(ack, close_writer=False)
        waits = iter((True, False))
        try:
            with self.assertRaises(self.protocol.ProtocolError):
                self.protocol.read_publication_ack_channel(
                    read_fd,
                    deadline=4.0,
                    canonical_record_bytes=canonical,
                    monotonic=lambda: 3.0,
                    wait_readable=lambda _fd, _remaining: next(
                        waits,
                        False,
                    ),
                )
        finally:
            _close_fd(write_fd)
            _close_fd(read_fd)

    def test_result_pipe_writes_and_reads_one_canonical_object_and_eof(
        self,
    ) -> None:
        result = _controller_result_record()
        expected = _canonical_json_fixture(result)
        read_fd, write_fd = os.pipe()
        try:
            emitted = self.protocol.write_publication_result_channel(
                write_fd,
                result=result,
                expected_schema=CONTROLLER_RESULT_SCHEMA,
                expected_fields=CONTROLLER_RESULT_FIELDS,
            )
            write_fd = None
            self.assertEqual(emitted, expected)
            self.assertEqual(os.read(read_fd, len(expected) + 1), expected)
            self.assertEqual(os.read(read_fd, 1), b"")
        finally:
            _close_fd(write_fd)
            _close_fd(read_fd)
        self.assertEqual(self._read_result(expected), result)

