    def test_publication_helpers_do_not_fall_back_to_rename_or_acl_success(
        self,
    ) -> None:
        sources = tuple(
            pathlib.Path(module.__file__).read_text(encoding="utf-8")
            for module in (self.protocol, _runner(), _verifier())
        )
        for source in sources:
            self.assertNotIn("os.rename(", source)
            self.assertNotIn("os.replace(", source)
        self.assertIn("RENAME_EXCL", sources[0])
        self.assertIn("ACL_TYPE_EXTENDED", sources[0])

