    def test_leaf_existing_and_racing_destination_types_are_unchanged(
        self,
    ) -> None:
        kinds = (
            "regular",
            "directory",
            "symlink",
            "hardlink",
            "fifo",
            "socket",
        )
        for leaf_kind in ("payload", "checkpoint"):
            for destination_kind in kinds:
                operations = _FakeLeafPublicationIO(
                    leaf_kind,
                    destination_kind=destination_kind,
                )
                with self.subTest(
                    leaf_kind=leaf_kind,
                    destination_kind=destination_kind,
                    race=False,
                ):
                    with self.assertRaises(FileExistsError):
                        self._publish_leaf(leaf_kind, operations)
                    self.assertEqual(
                        operations.foreign_destination,
                        operations.foreign_before,
                    )
                    self.assertFalse(operations.committed)
                    self.assertNotIn("rename_exclusive", operations.events)
                racing = _FakeLeafPublicationIO(
                    leaf_kind,
                    race_at_rename=True,
                    race_kind=destination_kind,
                )
                with self.subTest(
                    leaf_kind=leaf_kind,
                    destination_kind=destination_kind,
                    race=True,
                ):
                    with self.assertRaises(FileExistsError):
                        self._publish_leaf(leaf_kind, racing)
                    self.assertEqual(
                        racing.foreign_destination,
                        racing.foreign_before,
                    )
                    self.assertEqual(
                        racing.foreign_destination["kind"],
                        destination_kind,
                    )
                    self.assertFalse(racing.committed)
                    self.assertEqual(racing.unlink_calls, [])

