    def test_controller_child_postcommit_failures_and_immediate_death_do_not_rollback(
        self,
    ) -> None:
        for operation in _FakeControllerChildIO.POSTCOMMIT:
            operations = _FakeControllerChildIO(fail_at=operation)
            with self.subTest(operation=operation):
                with self.assertRaises(_InjectedPublicationFailure):
                    self._run_controller_child(operations)
