    def test_controller_artifact_basename_enforces_suffix_headroom_before_native(
        self,
    ) -> None:
        self.assertEqual(len(PUBLICATION_NAME_SUFFIX), 52)
        accepted = (
            ("a" * 203, 255),
            ("a" * 12, 64),
        )
        for basename, name_max in accepted:
            operations = _FakeControllerChildIO(name_max=name_max)
            with self.subTest(length=len(basename), name_max=name_max):
                self._run_controller_child(operations, basename=basename)
                self.assertEqual(
                    operations.native_calls[0][3],
                    basename.encode("ascii"),
                )
        invalid = (
            ("", 255),
            (".", 255),
            ("..", 255),
            ("a/b", 255),
            ("a\\b", 255),
            ("a\x00b", 255),
            ("a\nb", 255),
            ("caf\u00e9", 255),
            ("a" * 204, 255),
            ("a" * 13, 64),
        )
        for basename, name_max in invalid:
            operations = _FakeControllerChildIO(name_max=name_max)
            with self.subTest(
                basename=repr(basename),
                name_max=name_max,
            ):
                with self.assertRaises(self.protocol.ProtocolError):
                    self._run_controller_child(
                        operations,
                        basename=basename,
                    )
                self.assertEqual(operations.native_calls, [])
        for name_max in (None, 0, -1, True, 255.0):
            operations = _FakeControllerChildIO(name_max=name_max)
            with self.subTest(name_max=name_max):
                with self.assertRaises(self.protocol.ProtocolError):
                    self._run_controller_child(
                        operations,
                        basename="pilot",
                    )
                self.assertEqual(operations.native_calls, [])

