            update = 512
            path = "checkpoints/update-000512.f5w"
            original = self.bundle["checkpoints"][update]
            mutated = bytearray(original)
            value = struct.unpack_from("<f", mutated, 0)[0]
            struct.pack_into("<f", mutated, 0, value + 0.125)
            mutated = bytes(mutated)
