@requires_implementation
@unittest.skipUnless(
    _exact_final_consumer_unavailability() is None,
    "real renameatx_np/APFS integration requires the frozen exact host",
)
class F5RecurrentPpoDarwinPublicationIntegration(unittest.TestCase):
    def setUp(self) -> None:
        self.protocol = _protocol()
        self.libc = ctypes.CDLL(None, use_errno=True)

    def test_real_same_directory_file_publication_and_collision(self) -> None:
        with tempfile.TemporaryDirectory(
            prefix="f5-real-renameatx-"
        ) as tmp:
            root = pathlib.Path(tmp)
            source = root / "source"
            destination = root / "destination"
            source.write_bytes(b"complete-source")
            descriptor = os.open(root, os.O_RDONLY | os.O_DIRECTORY)
            try:
                self.protocol.exclusive_rename_new(
                    self.libc,
                    descriptor,
                    source.name,
                    descriptor,
                    destination.name,
                )
                self.assertFalse(source.exists())
                self.assertEqual(destination.read_bytes(), b"complete-source")
                second = root / "second"
                second.write_bytes(b"second-source")
                before = destination.stat()
                with self.assertRaises(FileExistsError):
                    self.protocol.exclusive_rename_new(
                        self.libc,
                        descriptor,
                        second.name,
                        descriptor,
                        destination.name,
                    )
                after = destination.stat()
                self.assertEqual(second.read_bytes(), b"second-source")
                self.assertEqual(destination.read_bytes(), b"complete-source")
                self.assertEqual(
                    (before.st_dev, before.st_ino),
                    (after.st_dev, after.st_ino),
                )
            finally:
                os.close(descriptor)

    def test_real_high_level_payload_publication_and_directory_fsync(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory(
            prefix="f5-real-high-level-payload-"
        ) as tmp:
            payload = b'{"schema":"bloodbowl-f5-fixture-v1"}\n'
            operations = _RealDarwinLeafPublicationIO(
                self.protocol,
                self.libc,
                tmp,
                destination_basename="protocol.json",
                payload=payload,
            )
            try:
                self.protocol.publish_payload_leaf(
                    operations,
                    relative_path="protocol.json",
                    payload=payload,
                    semantic_sha256=hashlib.sha256(
                        b"f5-canonical-json-v1\0" + payload
                    ).hexdigest(),
                )
                destination = pathlib.Path(tmp) / "protocol.json"
                self.assertEqual(destination.read_bytes(), payload)
                stat_result = destination.stat()
                self.assertEqual(stat_result.st_mode & 0o777, 0o600)
                self.assertEqual(stat_result.st_nlink, 1)
                self.assertEqual(
                    tuple(operations.events),
                    (
                        "validate_payload_semantics",
                        *_FakeLeafPublicationIO.PRECOMMIT[1:],
                        *_FakeLeafPublicationIO.POSTCOMMIT,
                    ),
                )
                self.assertLess(
                    operations.events.index("fsync_temporary_file"),
                    operations.events.index("rename_exclusive"),
                )
                self.assertEqual(
                    operations.events[-1],
                    "fsync_containing_directory",
                )
            finally:
                operations.close()

